    },
    {
      "name": "支配时空的邪眼王 (Aion Barroll)",
      "description": "由“停止世界的邪眼”进化而来的新型神灭具。除了强化时间停止效果外，还能干涉空间的物理结构，制造出无法修复的次元裂缝。其威力评价被公认为超越了普通的魔王级。"
    },
    {
      "name": "禁夜与真暗之翳的朔兽 (Forbidden Invade Balor the Beast)",
      "description": "加斯帕的禁手（Balance Breaker）形态。释放出覆盖城镇规模的、具有吞噬属性的深渊黑暗，并从中制造出大量的暗兽群。在此状态下，加斯帕的体能与魔力会呈现出神灵级的爆发，受到的伤害连圣杯都无法治愈。"
    },
    {
      "name": "巴罗尔之眼 (Evil Eye of Balor)",
      "description": "由于是凯尔特魔神巴罗尔意识碎片的转世，他在极度愤怒时能发动近似“直死之魔眼”的概念性杀伤，直接从根源上抹除目标的生命反应或因果律。"
    },
    {
      "name": "吸血鬼异能",
      "description": "身为吸血鬼中的“昼行者”，拥有极高的阳光耐性。擅长操控蝙蝠群、操控影子、制造血液契约等。其影子本身就是通往异空间的入口。"
    }
  ],
  "relationships": {
    "兵藤一诚": {
      "nature": "崇拜的对象、精神支柱、唯一愿意喝血的对象",
      "description": "一诚不仅解开了他的封印，还接纳了他怪异的性格。对加斯帕来说，一诚是光，是无可取代的家人。为了守护一诚，他可以舍弃卑微的自卑感，化身为最恐怖的魔神。"
    },
    "莉雅丝·吉蒙里": {
      "nature": "主人、救命恩人、敬畏的学姐",
      "description": "莉雅丝将其从迫害中救出并收为眷属，加斯帕对莉雅丝抱有绝对的忠诚，视其为在这个世界上真正的归宿。"
    },
    "塔城小猫": {
      "nature": "同班同学、战友",
      "description": "两人同为一年级，同样有着被家族背叛或被迫害的经历，性格虽然一冷一热，但配合极其默契，是眷属中年轻一代的双璧。"
    },
    "瓦雷莉·采佩什": {
      "nature": "青梅竹马、守护对象",
      "description": "吸血鬼阵营中的重要人物，加斯帕在经历过吸血鬼内乱后，发誓要保护这位有着悲惨遭遇的同族少女。"
    }
  }
}

