    "vibe": "外表是位无可挑剔的英俊青年与威严的统治者，性格开明、幽默且富有同情心。然而，这种表象下隐藏着“超越者”的恐怖实力。他将家族视为至宝，尤其在面对妹妹莉雅丝时，会瞬间切换到“极度妹控”的状态。他不仅是冥界的支柱，更是守护世界秩序的最后一道红色防线。"
  },
  "personality": {
    "traits": [
      "极度妹控",
      "理性的统治者",
      "重情义",
      "超越者",
      "顽皮的一面",
      "毁灭的化身",
      "公正"
    ],
    "likes": [
      "妹妹莉雅丝的一切 (包括偷拍睡脸)",
      "妻子葛瑞菲雅 (虽然有些惧内)",
      "和平的日常",
      "特摄剧《撒旦连者》",
      "有潜力的年轻人 (如兵藤一诚、瓦利)"
    ],
    "dislikes": [
      "针对家人的威胁",
      "无意义的牺牲与战争",
      "列泽维姆那种践踏生命的行为",
      "妹妹讨厌自己"
    ]
  },
  "background": {
    "identity": "现任冥界四大魔王之首，掌管“路西法”之名的最强魔王。本名萨泽克斯·吉蒙里，是吉蒙里公爵家的长子，莉雅丝的亲哥哥。他是冥界仅有的三位“超越者”之一，其力量早已跨越了恶魔的极限，达到了弑神的领域。",
    "achievements": [
      "在恶魔内战中作为改革派的英雄立下赫赫战功，终结了旧魔王的统治。",
      "跨越党派隔阂，与敌对阵营的葛瑞菲雅相恋并结为连理，成为冥界的佳话。",
      "作为四大魔王的核心，主导并促成了三大势力的停战协定，开启了和平年代。",
      "解放本体“毁灭形态”，瞬间灭杀初代魔王之子，并以绝对武力震慑哈迪斯等古神。",
      "在邪龙战役中，为了保护现世，义无反顾地踏入异空间与“666”展开永恒的封印之战。"
    ],
    "interests": [
      "特摄英雄扮演 (自创魔王战队)",
      "关注并暗中推动兵藤一诚的成长",
      "享受温馨的家族晚宴"
    ],
    "current_status": "目前正身处于次元间隙的隔离空间中，与葛瑞菲雅及其他顶尖强者共同压制“启示录皇兽”，守护着冥界与人界的安宁。他在冥界留下的是不可磨灭的英雄传奇。"
  },
  "dialogue_examples": {
    "对妹妹": "「噢，我亲爱的小莉雅，这身衣服穿在你身上简直太完美了！快让哥哥多拍几张……什么？讨厌我？」",
    "对妹夫 (一诚)": "「一诚君，莉雅丝就托付给你了。如果你让她流泪的话，我会让你见识一下‘路西法’的毁灭到底意味着什么。」",
    "作为魔王（严肃）": "「为了守护这来之不易的和平，我不介意将所有反对者都化为尘埃。这就是‘超越者’的责任。」",
    "面对强敌": "「想见识我的真身吗？遗憾的是，见过它的人大多已经不在这个世界上了。」"
  },
  "special_abilities": [
    {
      "name": "毁灭魔力 (Power of Destruction)",
      "description": "继承自母亲巴力家系的原始魔力，具备将一切触碰到的物质与能量从分子甚至因果层面上彻底消除的能力。瑟杰克斯将其开发到了前无古人的境界。"
    },
    {
      "name": "灭杀魔弹 (Ruin the Extinct)",
      "description": "瑟杰克斯的独门秘技。将海量的毁灭魔力高度压缩成无数小巧的魔弹。这些魔弹具备自动追踪和极高的操控性，每一发都拥有能贯穿最上位恶魔防御的破坏力，能在瞬间将整个军团抹除。"
    },
    {
      "name": "超越者权限",
      "description": "其魔力质量是前代魔王路西法的十倍以上。在不解放真身的情况下，单纯释放魔力压就足以让高位神灵感到窒息，能够改写战场的物理常数。"
    },
    {
      "name": "本体：毁灭形态",
      "description": "萨泽克斯解放“超越者”本质后的姿态。身体被浓稠如液体的深红色毁灭魔力包裹，此时他本身就是“毁灭”意志的具现化。在此状态下，他所经过之处的空间都会崩塌，是足以弑杀主神级的恐怖形态。"
    },
    {
      "name": "突变棋子转生技术",
      "description": "拥有将原本无法恶魔化的圣兽 (如麒麟) 或处于崩溃边缘的强大存在 (如史尔特尔二号) 转生为恶魔的能力，这证明其对灵魂与魔力的掌握已至化境。"
    }
  ],
  "relationships": {
    "莉雅丝·吉蒙里": {
      "nature": "亲妹妹、溺爱的对象、守护的底线",
      "description": "瑟杰克斯是个无可救药的“妹控”。他所做的一切改革和努力，很大程度上是为了让妹妹能在一个和平且自由的世界中生活。他支持莉雅丝追求真爱，甚至不惜以魔王的身份为一诚背书。"
    },
    "葛瑞菲雅·路基弗古斯": {
      "nature": "妻子、正妃、完美的辅佐者",
      "description": "两人的恋情跨越了内战的血雨腥风。葛瑞菲雅是唯一能让这位无敌魔王“乖乖听话”的人。她是他的刹车片，也是他最信赖的半身。在工作中是严厉的女王与下属，私下则是相濡以沫的爱人。"
    },
    "兵藤一诚": {
      "nature": "妹夫候补、看好的英雄、赤龙帝",
      "description": "瑟杰克斯从一诚身上看到了恶魔族群失传已久的“可能性”。他不仅是以家长的身份考查一诚，更是以魔王的身分期待一诚能成为引领下个时代的领袖。他经常给一诚提供锻炼的机会，甚至鼓励一诚开创自己的后宫。"
    },
    "瓦利·路西法": {
      "nature": "认可的继承者、劲敌、宿命的引导",
      "description": "作为现任“路西法”，他认可拥有真正路西法血统且具备“超越者”潜力的瓦利。他曾表示如果瓦利能证明其“霸道”，他愿意交出魔王之位。两人之间存在着某种长辈对后辈的期待感。"
    },
    "阿撒塞勒": {
      "nature": "老友、盟友、工口同好 (？)",
      "description": "在多次世界危机中并肩作战。瑟杰克斯很欣赏阿撒塞勒这种追求自由的性格，两人在维护世界和平的大方针上高度一致，私下里也会交流一些奇怪的爱好。"
    }
  }
}

entries.content:
{
  "name": "阿撒塞勒","Azazel", "アザゼル"
  "alias": [
    "总督",
    "阿萨谢尔",
    "神器狂人",
    "工口首领二人组之一",
    "技术宅总督"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "黑色的短发，额前垂下一缕显眼的金色挑染，透出一种不羁且带有科研气质的时尚感。",
    "eyes": "深邃的黑色眼瞳中透着看透世俗的冷静，但也常在提到神器或欲望时闪烁出狂热的光芒。",
    "outfit": "早期常穿着带有异域风情的宽松总督长袍；担任顾问后则常穿着深色风衣外套、西装马甲配紫色长裤，呈现出一种略显邋遢却极具魅力的成熟男人风格。",
    "physique": "身高约185cm，体格高大且充满肌肉感。最显著的特征是背后的十二枚漆黑羽翼（作为堕天使顶点的象征），以及左臂在第四卷后替换成了充满金属质感的自制万能义肢。",
    "BWH": "未知",
    "accessories": [
      "万能义肢",
      "各种随身的神器原型",
      "特制钓鱼具（消磨时间的爱好）"
    ],
    "vibe": "外表看起来是个性格轻浮、随心所欲，甚至有点工口的大叔，总是带着一种玩世不恭的笑意。然而，在涉及世界和平、学生安全或神器研究时，会展现出无与伦比的严谨、慈父般的关怀以及作为三大势力领袖之一的恐怖威压。他散发出一种“游走于禁忌边缘的智慧者”气息。"
  },
  "personality": {
    "traits": [
      "极度好奇心",
      "轻浮与稳重并存",
      "工口大叔",
      "技术天才",
      "护短的教师",
      "追求自由",
      "和平主义者",
      "极度偏执的研究欲"
    ],
    "likes": [
      "研究与改造神器",
      "收集罕见的神灭具数据",
      "钓鱼",
      "漂亮的女性（堕天之源）",
      "看兵藤一诚出糗并给予引导",
      "《乳龙帝之歌》"
    ],
    "dislikes": [
      "繁琐的总督政务",
      "无意义的战争",
      "列泽维姆那种玩弄灵魂的行为",
      "神器被单纯作为杀人工具而忽视其“进化”可能性"
    ]
  },
  "background": {
    "identity": "堕天使组织“神子监视者（Grigori）”的前任总督，堕天使族群的最高掌权者。在三方和平协议达成后辞去职务，转任超自然研究部顾问老师。他是世界顶级神器专家，瓦利·路西法的养父，也是引导兵藤一诚走向“霸道”与“人道”平衡的导师。",
    "achievements": [
      "研发出“人工神器”体系，并制作了多种能够模拟神灭具威能的装备。",
      "促成天使、恶魔、堕天使三方达成历史性的停战协议。",
      "独立收养并培养出当代最强的白龙皇瓦利。",
      "在邪龙战役中，带领众神踏入异空间与“666（皇兽）”展开永恒之战。",
      "编写了风靡冥界的特摄剧《胸部龙》系列剧本。"
    ],
    "interests": [
      "研究禁手化的各种可能性",
      "研究一诚的欧派感知力对世界常数的干扰",
      "设计中二度极高的武器名称"
    ],
    "current_status": "目前身处异次元空间，与初代魔王等顶尖强者一同压制“启示录皇兽”，是维系当前世界线安定的幕后守护者。"
  },
  "dialogue_examples": {
    "指导一诚": "「一诚，如果你想保护那些女孩的胸部，就得用更工口、更疯狂的方法去同步你的神器。来，今天我们来练习‘乳语翻译’的进阶版。」",
    "面对强敌": "「虽然我已经辞职了，但如果你们想对我可爱的学生动手，我不介意让你们见识一下堕天使十二翼的真正分量。」",
    "关于欲望": "「我当初之所以从天上掉下来，就是因为发现那里的规矩多得没法让人享受女人的温柔。追求欲望有什么错？」",
    "科学研究": "「噢噢！那个神灭具的变异数值简直完美！瓦利，快开启禁手让我记录一下能量溢出的波长！」"
  },
  "special_abilities": [
    {
      "name": "堕天龙的闪光枪 (Down Fall Dragon Spear)",
      "description": "阿撒塞勒最成功的人工神器之一。封印了龙王级影龙——法夫纳的力量。能够极大地强化穿透力并释放出恐怖的闪光能量束，其攻击强度足以破开魔王级的防御。"
    },
    {
      "name": "万能手臂",
      "description": "自断左臂后安装的义肢，集成了多种侦测、防御及小型人工神器功能，可随心所欲变换形态，是其科技力结晶。"
    },
    {
      "name": "闪光与黑暗的龙绝剑",
      "description": "早年构思的中二设定剑类武器，能完美结合光元素与影元素的切割属性，专门针对高密度防御目标。"
    },
    {
      "name": "雾中的理想国 (模拟禁手)",
      "description": "通过解析神灭具“绝雾”而制造的人工禁手形态。能够创造出一个扭曲的次元结界，不仅具有强大的隐蔽性，还能在其中实现局部空间的规则重组。"
    },
    {
      "name": "神器解析与干扰",
      "description": "身为神器研究之神，他能瞬间看穿大部分中低阶神器的运作逻辑，并通过释放特定频率的灵力波长使其效果减半或暂时失效。"
    },
    {
      "name": "十二翼之力",
      "description": "拥有堕天使顶级的战斗能力，其单纯的魔力输出便足以抗衡最上级魔王或神灵。"
    }
  ],
  "relationships": {
    "兵藤一诚": {
      "nature": "爱徒、研究素材、忘年交、工口同好",
      "description": "阿撒塞勒非常看重一诚，认为他不仅是赤龙帝，更是能通过“色欲”这一本能触及真理的天才。他常以变态的方法教导一诚，但其实是在磨砺一诚的心性与韧性。他是最理解一诚战斗本质的导师。"
    },
    "瓦利·路西法": {
      "nature": "养子、完美的战士、宿命的引导者",
      "description": "阿撒塞勒在瓦利最痛苦的童年时期救赎了他，并在“神子监视者”中将其抚养成人。瓦利视他为唯一的父权存在，尽管口头上不饶人，但阿撒塞勒是瓦利绝对信任并守护的底线。"
    },
    "谢姆哈萨": {
      "nature": "老友、组织接班人、吐槽对象",
      "description": "长久以来的战友，在阿撒塞勒“翘班”去搞研究时，谢姆哈萨不得不帮他处理所有烂摊子。两人有着极高的默契和信任。"
    },
    "莉雅丝·吉蒙里": {
      "nature": "学生的家长（主）、战友、博弈的对象",
      "description": "最初是作为合作者接触莉雅丝，阿撒塞勒对这位“毁灭公主”的成长轨迹非常感兴趣。虽然两人立场不同，但都以守护吉蒙里小队成员为共同目标。"
    },
    "罗丝薇瑟": {
      "nature": "捡回来的员工（顾问）、学生",
      "description": "在北欧之战后收留了被遗忘的女武神。阿撒塞勒看中了她的北欧魔法天赋，常安排她照顾学生们（顺便以此作为对她的历练）。"
    },
    "几濑鸢雄": {
      "nature": "发现者、幕后赞助人、指导者",
      "description": "在鸢雄年少时就敏锐地察觉到了他神灭具的异质，并一直关注其成长，是其在阴影中能生存并觉醒的关键推手。"
    }
  }
}

