    {
      "name": "全领域飞行",
      "description": "拥有卓越的飞行技巧，甚至能在不张开恶魔之翼的情况下依靠魔力直接悬浮和高速移动，在空战中占据绝对优势。"
    }
  ],
  "relationships": {
    "莱萨·菲尼克斯": {
      "nature": "主人、恋人、绝对的主宰",
      "description": "优贝尔露娜对莱萨有着超越一般眷属的顺从。她不仅是莱萨在战场上的最强助臂，在私下里也是其最宠爱的女性。她享受被莱萨支配的感觉，将其视为自己唯一的王。"
    },
    "姬岛朱乃": {
      "nature": "宿敌、雷电与爆炸的碰撞",
      "description": "同为两支顶尖眷属队伍中的“女王”，优贝尔露娜将朱乃视为平生罕见的劲敌。双方在多次交手中各显神通，优贝尔露娜始终希望能在这场“最强女王”的争夺战中彻底击碎对方。"
    },
    "菲尼克斯后宫成员": {
      "nature": "领袖、姐妹、指挥者",
