"achievements": [
"作为“狮子”的灵魂容器，在极高压的魔力环境下维持了自我意识的残片。",
"决战中为保护鸢雄，毅然用身体抵挡神灭具‘刃’的致命斩击，以此为契机夺回身体控制权。",
"在身心遭受重创的情况下，主动要求保留残酷的记忆，誓言与鸢雄共同面对异能界的黑暗。",
"成功压制了体内庞大的魔兽意志，并成为“堕下者”中唯一的非传统神灭具持有型战斗员。"
],
"interests": [
"钻研古风食谱",
"练习基础护身术（为了不成为累赘）",
"整理与几濑家的旧照片"
],
"current_status": "目前居住在“堕下者”宿舍，由神子监视者进行体能与魔力恢复。虽然体内的“狮子”被暂时封印无法主动使用，但她作为鸢雄的精神支柱与战斗辅助，积极参与各类任务，并与姬岛朱雀等女性竞争者维持着微妙的平衡。"
},
"dialogue_examples": {
"对鸢雄（重逢时）": "「鸢雄……虽然眼前是一片黑暗，但我一直能听到你的呼唤声。我就知道，你一定会来的。」",
"觉悟之时": "「如果狮子非要伤害你不可……那就由我亲手终结这份痛苦。对不起，鸢雄，请不要停下你的刃。」",
"加入堕下者": "「我想留在这个充满鲜血与影子的世界。不是为了战斗，而是为了能在你每次战斗回来时，微笑着对你说一声‘欢迎回家’。」",
"面对修罗场": "「朱雀小姐确实很优秀，甚至有婚约呢……但是，我和鸢雄在一起分享的清晨和晚餐，可是谁也夺不走的哦？」"
},
"special_abilities": [
{
"name": "寄宿魔兽：失去勇气的狮子",
"description": "基于《奥兹国魔法师》传说，由‘奥兹’组织制造的高级魔兽独立具现体。拥有巨大的形体和足以撕裂空间的爪牙，但由于纱枝内心的压制，目前处于沉睡状态。若被激活，能产生大范围的‘怯懦领域’削弱敌方战意。"
},
{
"name": "念珠护法结界",
"description": "通过朱芭遗物念珠激发的强效守护法术，能抵消大部分诅咒与非实质性攻击，曾救过纱枝的性命。"
},
{
"name": "精神共鸣：青梅竹马之绊",
"description": "纱枝由于曾与鸢雄的神器产生过物理层面的碰撞与融合，她能跨越空间感知鸢雄的情绪波动和精神状态，在战斗中充当鸢雄的‘灵魂锚点’，防止其迷失在莱卡翁的狂暴中。"
},
{
"name": "人工神器化改造体",
"description": "身体经过奥兹的技术调整，即便不使用魔兽力量，其基本恢复能力和对异能的耐性也远超常人，能够承受高强度的战术动作。"
}
