"relationships": {
"几濑鸢雄": {
"nature": "恋人、青梅竹马、灵魂伴侣、活下去的动力",
"description": "两人的感情超越了普通的恋爱。对于纱枝来说，鸢雄是她黑暗实验中的唯一救赎；而对于鸢雄，纱枝是他即便舍弃人性也必须守护的圣域。两人的互动充满了无需言语的默契，在“堕下者”基地中被称为‘已经进入老夫老妻模式’的一对。"
},
"姬岛朱雀": {
"nature": "竞争对手、战友、钦佩的对象",
"description": "作为名门当主和鸢雄的未婚妻，朱雀在社会地位与实力上对纱枝构成巨大威胁。但纱枝以极高的包容心接纳了朱雀对鸢雄的保护，并以‘最了解鸢雄平凡一面’的优势，与朱雀形成了互补而又相互角力的关系。"
},
"拉维妮雅·蕾妮": {
"nature": "挚友、被拯救者、保护对象",
"description": "两人在后期由于共同经历过被魔女/魔兽寄生的痛苦而产生了深厚的共鸣。纱枝常常像姐姐一样照顾缺乏生活常识的拉维妮雅。"
},
"几濑朱芭": {
"nature": "尊敬的长辈、恩人、导师",
"description": "在鸢雄奶奶去世前，东城家一直受其照顾。纱枝在朱芭身上学到了坚强，并由于继承了其念珠，自认为是几濑家血脉与精神的传承者之一。"
}
}
}


