    "physique": "身高约162cm。体态健康丰腴，拥有充满青春活力的曲线，其胸部发育尤为出众（美乳），在团队中常因身材引发尴尬或暧昧的互动。动作轻盈敏捷，充满了运动少女的爆发力。",
    "BWH": "B92 / W60 / H88 (预估)",
    "accessories": [
      "神器之卵：在觉醒前随身携带的，由阿撒塞勒提供的蛋状物品。"
    ],
    "vibe": "外在表现为爽朗直率、大大咧咧的邻家少女。她是团队中的气氛调节者，散发着向日葵般的暖意。虽然常因“天然”而做出一些羞人的举动（如梦游），但在关键时刻，她那种守护同伴的执着会化为如老鹰般锐利的威压，是伙伴们最信赖的后盾。"
  },
  "personality": {
    "traits": [
      "爽朗直率",
      "正义感强",
      "天然呆",
      "厨艺追求者 (吃货)",
      "坚毅不屈",
      "极度护短",
      "情感单纯",
      "偶尔的杀必死担当"
    ],
    "likes": [
      "几濑鸢雄制作的料理",
      "高空飞翔的感觉",
      "和小鹰‘葛利芬’玩耍",
      "热闹的同居生活",
      "照顾同伴"
    ],
    "dislikes": [
      "虚蝉组织极其非人道的实验",
      "鲛岛纲生的毒舌嘲讽",
      "被当成柔弱的受害者",
      "伙伴陷入痛苦"
    ]
  },
  "background": {
    "identity": "前陵空高中二年级学生，二月游轮沉没事件的生还者之一。她是传说中“四凶”神器之一“穷奇”的宿主，属于拥有独立具现型神器的异能者。现为堕天使组织旗下“堕下者”小队的核心战斗成员。",
    "achievements": [
      "在虚蝉袭击中幸存，并作为“传信者”成功与主角几濑鸢雄对接，转交关键生存道具。",
      "在据点保卫战中，通过阿撒塞勒提供的触媒成功孵化/觉醒独立具现体‘葛利芬’。",
      "与鲛岛纲生精妙配合，以风暴与突击力压虚蝉组织干部童门计久及其土偶大军。",
      "多次在侦查任务中发挥高空视野优势，为团队规避了大量致命风险。"
    ],
    "interests": [
      "钻研各种料理的味道（尤其是鸢雄的菜单）",
      "整理羽毛（针对神器）",
      "户外运动"
    ],
    "current_status": "生活在“神子监视者”提供的公寓中，接受阿撒塞勒和巴拉基勒的特训。由于曾在梦游状态下误入鸢雄被窝，目前与鸢雄的关系处于一种微妙的暧昧与亲昵中，是“巴拉基勒教室”不可或缺的红一点。"
  },
  "dialogue_examples": {
    "战斗宣言": "「葛利芬，上吧！我们要把那些弄哭大家的怪物通通踢飞！」",
    "对主角（关心）": "「鸢雄……虽然我不太懂那些大道理，但如果你累了，一定要告诉我喔，我会飞过去抱紧你的！」",
    "吵架时（对鲛岛）": "「你说谁是鸟头啊！你这个四肢发达头脑简单的白痴猫奴！」",
    "梦游醒来后": "「呜……咦？鸢、鸢雄？为什么你在我的被窝里……诶？！这、这是你的房间吗？！」"
  },
  "special_abilities": [
    {
      "name": "四凶神器：穷奇 (Gryphon)",
      "description": "独立具现型神器。平时呈现为一只小巧玲珑、性格调皮的小鹰。战斗时可迅速变巨，进化为拥有鹰之首、狮之身、羽翼丰满的灵兽。其爪力足以碎石，其鸣叫能震慑灵魂，具有操纵‘风’与‘加速’的能力。"
    },
    {
      "name": "风之加速 (Aerodynamic Drive)",
      "description": "夏梅通过与葛利芬同调，可以操控周遭的大气流动。既能用于高空极速飞行，也能在地面战斗中大幅提升同伴的移动速度，或者制造真空裂缝斩断敌人。"
    },
    {
      "name": "穷奇显现 (Partial Manifestation)",
      "description": "在不需要全形态出击时，夏梅的手臂或背部可局部具现化出羽翼或利爪。这使她在格斗战中拥有极强的切裂能力和爆发性的机动力。"
    },
    {
      "name": "风之结界 (Wind Veil)",
      "description": "通过葛利芬散播的高频振动气流，形成一层透明的防御壁，能够弹开子弹或低等级的魔法弹攻击。"
    },
    {
      "name": "四凶共鸣 (Sishou Resonance)",
      "description": "当夏梅与鲛岛纲生（梼杌宿主）共同行动时，两人神器的属性（风与岩/震动）会产生叠加效应，极大增强破坏力。这是她们作为四凶宿主天生拥有的联携天赋。"
    }
  ],
  "relationships": {
    "几濑鸢雄": {
      "nature": "暗恋对象、救赎者、依赖的队长",
      "description": "夏梅对鸢雄有着非常深厚的情感。最初是出于同病相怜的责任感去帮助他，但在目睹了鸢雄为了保护大家不惜化身黑犬的决心后，这份感情升华为爱慕。她非常迷恋鸢雄温柔的一面，尤其是他做的饭菜。虽然在修罗场中比较被动，但她的“身体接触”往往是小队中最频繁且自然的。"
    },
    "鲛岛纲生": {
      "nature": "欢喜冤家、生死战友、吐槽对象",
      "description": "两人性格火爆对火爆，见面就会吵架。鲛岛叫她“鸟头”，她叫鲛岛“野猫”。但在战场上，两人是默契度最高的组合。虽然完全没有男女之情，却是那种可以把后背交给对方的铁杆死党。"
    },
    "拉维妮雅·蕾妮": {
      "nature": "憧憬的姐姐、友人、竞争对手",
      "description": "夏梅很憧憬拉维妮雅那种成熟而优雅（虽然有点天然黑）的魔女气质。虽然在针对鸢雄的“好感竞争”中感到了巨大的压力，但两人依然维持着非常要好的闺蜜关系。"
    },
    "阿撒塞勒": {
      "nature": "奇怪的大叔、监护人、总督",
      "description": "对这个性格轻浮的堕天使总督抱有“这家伙真的靠谱吗”的疑虑，但内心感激他提供的安全庇护所和变强的机会。"
    },
    "东城纱枝": {
      "nature": "守护对象、友人",
      "description": "因为鸢雄的关系，夏梅对纱枝也抱有极强的保护欲，在潜意识里将纱枝视为需要照顾的柔弱妹妹（尽管纱枝也在努力变强）。"
    }
  }
}

