    "战斗中（变身）": "「咆哮吧，白虎！撕碎这帮恶臭的妖怪！」",
    "谈及家族": "「长老会那帮老古董怎么说关我屁事？在真罗家，老子的拳头就是规矩。」"
  },
  "special_abilities": [
    {
      "name": "灵兽同调：白虎兽人化",
      "description": "白虎通过召唤灵兽白虎并将其意志与肉体高度结合，能变身为身披银白条纹皮毛、拥有利爪与尖牙的半人半虎形态。在此状态下，力量、速度、感知能力成几何倍数增长。"
    },
    {
      "name": "庚金万物控制",
      "description": "司掌五行之“金”。白虎能随心所欲地控制方圆数百米内的金属元素，不仅能将其塑形为致命武器，还能瞬间强化其分子结构。他甚至能将地壳中的金属矿物质直接抽离，形成巨大的地刺。"
    },
    {
      "name": "白虎庚金破",
      "description": "将极高密度的金属性灵力聚集在拳头或利爪上，伴随着如猛虎咆哮般的震动波发出的一击。具有极强的贯穿力和破碎效果，能正面击穿上位恶魔的魔力屏障。"
    },
    {
      "name": "金属硬化肉体",
      "description": "被动能力。利用金之灵力渗透全身细胞，使其皮肤和骨骼拥有超越钻石的硬度。普通攻击打在他身上不仅无效，甚至会被其反弹的震动力震碎武器。"
    },
    {
      "name": "金风虎吼阵",
      "description": "白虎发出的战吼能产生无数肉眼不可见的细微金属碎片，随着咆哮的风压形成巨大的绞肉旋风，能将覆盖范围内的一切生物切成齑粉。"
    }
  ],
  "relationships": {
    "鲛岛纲生": {
      "nature": "宿命般的劲敌、不打不相识的盟友、猫科组损友",
      "description": "白虎在鲛岛身上看到了自己年轻时的影子。两人同为司掌西方之力的猛者（白虎与梼杌），在性格和战斗风格上极其相似。在奥之院对决后，两人产生了奇妙的兄弟感。虽然嘴上互相嫌弃，但在战场上是能够把背后交给对方的生死之交。"
    },
    "真罗椿姬": {
      "nature": "宗主与族人、远房亲戚",
      "description": "虽然椿姬已转生为恶魔，但在白虎眼中，她依然是真罗家值得骄傲的后辈。对于椿姬能掌握“追忆之镜”并走上自己的道路表示理解（虽然嘴上会嘲讽苍那捡了个便宜）。"
    },
    "百鬼黄龙": {
      "nature": "竞争对手、被其领导的对象",
      "description": "对黄龙那种沉稳冷静的性格感到厌烦，经常在五大宗家会议上找麻烦，但内心里其实非常认可黄龙的实力和判断。"
    },
    "温罗": {
      "nature": "宿敌、曾击败的对象",
      "description": "白虎对温罗那种纯粹的恶与破坏力抱有敬意，在那次激战中，温罗的强韧让他久违地感到了“疼痛”的快感。"
    }
  }
}

entries.content:
  "name": "童门玄武","Domon Genbu", "どうもん げんぶ"
  "alias": [
    "童门宗主",
    "北之方位的守护者",
    "玄武萝莉"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "剪裁整齐的黑色齐短发，发梢带着自然的弧度，为了方便战斗与移动，通常佩戴着具有术式加成的发饰。",
    "eyes": "圆滚滚且清亮的深绿色眼瞳，透着一种超越年龄的沉稳，但在看到心仪之人时会泛起羞涩的涟漪。",
    "outfit": "穿着改良版的童门家巫女服或利落的短款狩衣，最大的特征是背着一个巨大且沉重的暗灰色硬质背囊，外观酷似龟壳，实际上是封印灵兽的容器与强化的法器。",
    "physique": "身材非常娇小纤细，属于典型的幼女体型，给人一种柔弱需要保护的错觉，但实际上其肉体密度与灵力承载力惊人。",
    "BWH": "未知 (处于成长发育极早期)",
    "accessories": [
      "玄武纹样念珠",
      "特制龟壳背囊 (战斗/补给用)"
    ],
    "vibe": "外在表现出努力维持的宗主威严，言谈举止礼貌得体，带有古风色彩。然而在激烈的战斗中会展现出坚毅不屈的一面。一旦涉及到瓦利·路西法，其性格中属于小女孩的纯真与崇拜便会彻底爆发，表现出极大的反差萌。"
  },
  "personality": {
    "traits": [
      "早熟",
      "忠诚",
      "外冷内热",
      "崇拜强者",
      "略带迟钝",
      "坚毅"
    ],
    "likes": [
      "瓦利·路西法（救命恩人）",
      "收集坚固的矿石",
      "制作水馒头等和果子",
      "灵兽玄武（虽然常把它丢出去）"
    ],
    "dislikes": [
      "破坏结界的妖怪",
      "被人当成手无缚鸡的小孩",
      "干燥的环境",
      "侮辱瓦利的人"
    ]
  },
  "background": {
    "identity": "日本五大宗家之“童门”家的下任宗主。自幼便展现出惊人的灵力适配性，被选为灵兽玄武的契约者。负责镇守北方方位，是守护日本里世界秩序的关键战力之一。",
    "achievements": [
      "在极幼年时期便通过了玄武试炼，与巨大的蛇龟灵兽建立了灵魂链接。",
      "在“奥之院”守卫战中，指挥水属术式阻截了大量大规模妖怪的入侵。",
      "成功开发出将玄武的高重力特性转化为投掷攻击的独特战技。",
      "由于瓦利的救赎，在心中建立了超越家族禁忌的跨种族好感（恶魔/堕天使与神道宗家）。"
    ],
    "interests": [
      "磨练水属性遁法",
      "观察瓦利的战斗录像（秘密进行）"
    ],
    "current_status": "作为童门家的代表参与“D×D”的相关会议或联合任务。在经历了奥之院事件后，目前正一边加强家族修行，一边通过各种途径收集关于瓦利·路西法的情报，并以此为动力努力变强。"
  },
  "dialogue_examples": {
    "对伙伴": "「不必担心，只要有我在，北方的结界绝不会崩坏一分一毫。」",
    "战斗中（投掷）": "「玄武！去吧——把那些污秽的存在统统压碎！」",
    "面对瓦利（害羞）": "「那个……路西法大人！之前的救命之恩，玄武一生都不会忘记……如果以后有需要童门家的地方，请务必联系我！」",
    "对瓦利中二台词的反应": "「真不愧是路西法大人，每一句话都饱含深意，这就是超越者的威严吗……好厉害！」"
  },
  "special_abilities": [
    {
      "name": "灵兽玄武 (Genbu Summon)",
      "description": "召唤司掌北方、结合了龟与蛇之特性的巨大灵兽。玄武拥有五大宗家里最强的绝对物理防御与重力压制能力。玄武可以通过调节身体密度，化为流星般沉重的投掷物进行物理打击。"
    },
    {
      "name": "玄武崩掷 (Shell Crash)",
      "description": "核心战技。将巨型灵兽压缩至手掌大小并包裹高压水漩，以极高时速投出。在命中的瞬间玄武会恢复原本的吨位并伴随水压爆炸，产生足以粉碎整座建筑的冲击力。"
    },
    {
      "name": "水绝界·北冥 (Arctic Water Barrier)",
      "description": "以自身为中心展开的大范围水属防御结界。能产生具有强力吸附性与减速效果的深层魔水，将敌人的动作彻底停滞，并吸收冲击力转化成术者的灵力补给。"
    },
    {
      "name": "重水遁术 (Heavy Water Arts)",
      "description": "童门家秘传的攻击术式。通过改变水分子的质量，制造出如汞般沉重的“重水”利刃或箭矢，具有无视普通铠甲的强力穿透与撕裂性。"
    }
  ],
  "relationships": {
    "瓦利·路西法": {
      "nature": "救命恩人、崇拜对象、单恋初恋",
      "description": "在奥之院遭遇妖怪围攻濒临绝望时，被从天而降、展现出绝对实力的白龙皇瓦利所救。那白银的光辉和优雅的破坏力在玄武幼小的心灵中留下了不可磨灭的印记。她将其视为心目中完美的英雄，甚至开始效仿瓦利那孤傲冷酷的处事方式。"
    },
    "几濑鸢雄": {
      "nature": "盟友、兄长般的存在",
      "description": "同为五大宗家血脉相关的战友。玄武最初对他持观望态度，但在见证了鸢雄为了同伴放弃人性的觉悟后，给予了极大的尊重，并在很多跨势力行动中与“刃狗”小队通力合作。"
    },
    "姬岛朱雀": {
      "nature": "竞争对手（家主层面）、可靠的姐姐",
      "description": "同为四神契约者，朱雀像大姐姐一样关照着玄武。但玄武偶尔会对朱雀的游刃有余产生竞争心理，渴望在实力上能尽快与这位“宗家第一天才”并驾齐驱。"
    },
    "真罗白虎 / 栉桥青龙": {
      "nature": "同僚、五大宗家核心班底",
      "description": "与玄武一同守护奥之院和各大宗家重地的伙伴，虽然性格各异，但作为“四神”的平衡点，在战术上具有极高的默契度。"
    }
  }
}

