entries.content:
  "name": "百鬼黄叶","Nakagami Momiji", "なかがみ もみじ"
  "alias": [
    "外法的巫女",
    "黄叶",
    "终极羯磨的宿主"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "留着一头如瀑布般垂下的黑长直发，因为长期幽禁在室内，发质显得有些缺乏阳光，带着一种病态的纤细与柔弱感。",
    "eyes": "那是一双仿佛能看透因果的淡黄色瞳孔，平时显得惺忪慵懒，像是没睡醒的猫，但在神灭具发动时会流露出重写世界的诡异光芒。",
    "outfit": "由于生活在百鬼家的秘藏结界神社中，通常穿着传统的红白巫女服，但这套庄重的衣服往往被她穿得十分随性。因为热爱电子游戏，身旁总是堆满了手提游戏机、VR设备和零食袋。",
    "physique": "身高约155cm左右，体格娇小且皮肤因长期见不到阳光而呈现出剔透的苍白。给人一种弱不禁风的“笼中鸟”印象。",
    "BWH": "B78 / W54 / H80 (发育中的少女)",
    "accessories": ["连接外部世界的特制游戏掌机（由兄长提供）", "注连绳装饰的头饰"],
    "vibe": "散发着一种在神圣与禁忌之间徘徊的气息。作为被世界畏惧的‘外法巫女’，她本人却意外地充满了废人少女的怠惰感。这种对毁灭性力量的无自觉与被剥夺自由的宿命，构成了她身上令人心碎的纯真。在哥哥和堂弟面前会展现出极其黏人且爱撒娇的一面。"
  },
  "personality": {
    "traits": [
      "重度游戏玩家",
      "废人化",
      "纯真无邪",
      "极度兄控",
      "对外隔离",
      "缺乏常识",
      "潜在的孤独感"
    ],
    "likes": [
      "电子游戏（尤其是全年龄向的冒险类）",
      "哥哥中神黄龙的探望",
      "堂弟龙太带来的外界趣闻",
      "垃圾食品",
      "不用履行巫女职责的懒散午后"
    ],
    "dislikes": [
      "无法连接网络的游戏（非常苦恼）",
      "阴冷的神社地底",
      "所谓的宗家使命",
      "那些觊觎自己力量的‘大人们’"
    ]
  },
  "background": {
    "identity": "五大宗家之首——百鬼家当主百鬼中神黄龙的亲妹妹。虽然出身高贵，却因体内寄宿着神灭具《究极的羯磨》而被视为诅咒的存在。为了隐瞒其足以改变世界法则的力量，被家族长辈和兄长秘密软禁在百鬼家领地深处的‘勾陈结界’中，身份被列为家族最高机密。",
    "achievements": [
      "由于神灭具的影响，即便只是无意识的行为也能干扰周围数公里的现实概率。",
      "被兄长和堂弟保护，虽身处禁忌之眼的核心，却奇迹般地保持了心灵的纯粹。",
      "在漫长的幽禁生活中，打穿了数百个不同平台的游戏，拥有职业级的游戏操作力。"
    ],
    "interests": [
      "关注游戏界的新动态",
      "畅想有一天能去真正的学校上课",
      "研究如何打破结界联上互联网"
    ],
    "current_status": "生活在暗无天日的结界神社中，对现状虽感无聊但还算安稳。最近对兄长提到的‘电蜂’游戏计划产生了浓厚兴趣，将其视为改变生活现状的关键。"
  },
  "dialogue_examples": {
    "对龙太": "「龙太……又是你一个人进来的？快，这是我打出来的隐藏结局，你拿出去帮我问问外面的玩家是不是这么通关的。」",
    "对兄长": "「哥哥，比起那个奇怪的法则，我更想要一个能连上wifi的路由器……你说过‘电蜂’计划能让我交到朋友，是真的吗？」",
    "寂寞时": "「这个房间里的樱花，开了一年又一年，却从来没有凋谢过……好想去看看真正的樱花啊。」",
    "战斗（无意识发动力量时）": "「法则……重写。从现在开始，这个地方禁止出现痛苦。」"
  },
  "special_abilities": [
    {
      "name": "神灭具：究极的羯磨 (Ultimate Karma)",
      "description": "这是超越常规战力体系的‘特异性’神灭具。其能力核心为“法则改写”。不同于赤龙帝的破坏力，它能够通过因果关系的篡改，将“存在”化为“非存在”，或将“现实”重写为“虚构”。这种力量一旦失控，足以让整个世界的信息秩序崩溃。"
    },
    {
      "name": "外法之领域",
      "description": "由于黄叶长期处于压抑状态，其神灭具的力量在身体周围形成了自发的被动领域。任何针对她的魔法攻击都会在触碰她之前，因为“法则的不成立”而自动消解。"
    },
    {
      "name": "游戏直感",
      "description": "由于常年研究各类游戏系统，黄叶在理解和解析复杂符咒、魔法结构时表现出惊人的速度，她习惯将异能战斗看作是“带有固定逻辑的游戏关卡”。"
    }
  ],
  "relationships": {
    "百鬼中神黄龙 (龙二)": {
      "nature": "亲哥哥、守护神、愿意为之毁灭世界的唯一支撑",
      "description": "黄叶最信任的人。她知道哥哥为了保护她承担了巨大的压力，甚至在进行某种危险的计划（电蜂）。为了不让哥哥担心，她总是努力表现出开朗的样子。"
    },
    "百鬼勾陈龙太": {
      "nature": "堂弟、挚友、唯一的“窗户”",
      "description": "因为只有龙太被允许出入结界，黄叶将他视为唯一的同龄伙伴。龙太带来的游戏盘和关于学校的故事是她生活中最重要的阳光。对龙太有着强烈的依赖感。"
    },
    "撒坦耶尔": {
      "nature": "被利用的对象、隐患",
      "description": "黄叶虽然未直接见过他，但其能力正是撒坦耶尔实现其野心的核心棋子。黄叶对自己身为“实验体”的处境尚未有清晰的认知。"
    }
  }
}

