entries.content:
  "name": "姬岛唐棣","Himejima Karatake", "ひめじま からたけ"
  "alias": [
    "虚蝉机关首领",
    "姬岛家的弃儿"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "深褐色的短发，发型凌乱却带着一种狂野的侵略感，发梢微微向上翘起，显得桀骜不驯。",
    "eyes": "目光阴沉冷酷，眼底深处常驻着名为“复仇”的癫狂，瞳孔在操纵异能时会流露出浑浊的灵光。",
    "outfit": "常穿着一件质地优良但风格阴郁的深色西装长裤，外搭一件及膝的长款风衣，给人一种隐藏在阴影中的上位者压迫感。西装内部往往隐藏着大量符咒和邪术媒介。",
    "physique": "身高约182cm，身材高大挺拔，肩膀宽厚，虽然表面上是研究者风格，实则拥有极强的爆发力和肉体耐性。",
    "BWH": "未知",
    "accessories": [
      "特制指环：用于增幅邪术威力，同时也是远程操控虚蝉个体的核心终端。"
    ],
    "vibe": "散发着极度危险、偏执且扭曲的气息。他像是一头在黑暗中舔舐伤口太久、最终决定反噬一切的孤狼。作为被姬岛家抛弃的人，他的一举一动都充满了对“名门秩序”的嘲讽与摧毁欲。"
  },
  "personality": {
    "traits": [
      "冷酷无情",
      "偏执狂",
      "极度仇恨家族",
      "战术家",
      "毫无怜悯之心",
      "虐待狂倾向"
    ],
    "likes": [
      "看到名门家族的分崩离析",
      "几濑鸢雄陷入绝望的表情",
      "人体实验带来的进化结果",
      "复仇计划步步逼近的成就感"
    ],
    "dislikes": [
      "姬岛家的规矩与血统论",
      "无意义的温柔与善良",
      "名为“秩序”的谎言",
      "失败与不可控因素"
    ]
  },
  "background": {
    "identity": "虚蝉机关（Utsusemi）的首领。本质上是五大宗家之一姬岛家的远亲及弃儿，因自身能力的变异与家族排斥而走向极端。他是“二月游轮沉没事件”的直接策划者之一。",
    "achievements": [
      "成功解析了并大规模量产了人工怪物“虚蝉”，制造了震惊世界的邮轮失踪惨剧。",
      "在极短的时间内建立起规模庞大的地底基地，并秘密进行了“四凶计划”与“奥兹魔兽”植入实验。",
      "看穿了隐姓埋名的几濑家血脉，并将鸢雄引向了觉醒“刃狗”的修罗之路。",
      "几乎凭借一己之力动摇了五大宗家在日本异能界的统治根基。"
    ],
    "interests": [
      "研究禁忌的神器强化术",
      "观察实验体在极端心理压力下的崩溃过程"
    ],
    "current_status": "在虚蝉基地决战中，因利用东城纱枝威胁几濑鸢雄，触发了鸢雄彻底的“禁手”化。最终，他在无法理解的极致暴力面前，连同他扭曲的野心一起被“黑刃狗神”的乱刃碎尸万段，当场死亡。"
  },
  "dialogue_examples": {
    "对鸢雄（挑衅时）": "「呐，鸢雄，看着你最重要的青梅竹马像野兽一样咆哮、被冰冷的金属刺穿身体，这种感觉如何？让我看看吧，姬岛血脉中最黑暗的那部分……」",
    "谈及家族": "「姬岛、百鬼……那些坐拥光明的混蛋们根本不明白，只有在最深的阴影里，真正的力量才会萌发。我要用这股黑暗，烧毁那座虚伪的宗家之门。」",
    "绝命之时": "「哈哈哈哈……就是这样！这种让人战栗的力量……这就是‘刃狗’吗？真美啊……」"
  },
  "special_abilities": [
    {
      "name": "虚蝉操纵术",
      "description": "通过特制的灵力丝线与符咒，能够同时指挥成百上千只虚蝉怪物进行战术进攻，将对手瞬间淹没在虫潮与非人的血盆大口中。"
    },
    {
      "name": "人工神器开发：邪眼的领域",
      "description": "唐棣通过非法掠夺的神器碎片融合而成的临时结界，能够干扰周围空间的灵子流动，压制正统神器持有者的能力发挥。"
    },
    {
      "name": "姬岛流邪法·焦土",
      "description": "将姬岛家传统的火术扭曲后产生的黑炎，不具神圣感，专门用于腐蚀敌人的理智与灵魂。"
    },
    {
      "name": "失去勇气的狮子（操控权）",
      "description": "作为实验的最高负责人，他在初期拥有控制纱枝体内魔兽的最高权限，能强制命令狮子攻击任何人。"
    }
  ],
  "relationships": {
    "几濑鸢雄": {
      "nature": "宿敌、复仇的工具、命运的玩弄对象",
      "description": "唐棣将鸢雄视为达成自己向姬岛家报仇心愿的“完美兵器”。他不仅是鸢雄异能觉醒的推手，更是将其拖入地狱的恶魔。他从未把鸢雄当作对等的对手，而是一件渴望打磨出“最快之刃”的道具。"
    },
    "东城纱枝": {
      "nature": "实验体、筹码、牺牲品",
      "description": "在唐棣眼中，纱枝仅仅是用来刺激鸢雄觉醒的“最高级饲料”。他残忍地将其改造成狮子的人柱，并乐于欣赏纱枝在意识模糊中被推向战斗前线的痛苦。"
    },
    "几濑朱芭": {
      "nature": "曾经的畏惧对象、超越目标",
      "description": "虽然由于朱芭已死，两人没有直接互动，但唐棣一直生活在朱芭这位“最强几濑”的阴影下。他试图通过毁掉朱芭守护的孙子，来证明自己的道路超越了那个腐朽的时代。"
    },
    "姬岛宗家": {
      "nature": "憎恨的源泉",
      "description": "姬岛宗家的血统论与歧视造就了唐棣的疯狂，他余生所有的行动核心都是为了彻底铲除那个带给他屈辱的宗家。"
    }
  }
}

