      "description": "在唐棣眼中，纱枝仅仅是用来刺激鸢雄觉醒的“最高级饲料”。他残忍地将其改造成狮子的人柱，并乐于欣赏纱枝在意识模糊中被推向战斗前线的痛苦。"
    },
    "几濑朱芭": {
      "nature": "曾经的畏惧对象、超越目标",
      "description": "虽然由于朱芭已死，两人没有直接互动，但唐棣一直生活在朱芭这位“最强几濑”的阴影下。他试图通过毁掉朱芭守护的孙子，来证明自己的道路超越了那个腐朽的时代。"
    },
    "姬岛宗家": {
      "nature": "憎恨的源泉",
      "description": "姬岛宗家的血统论与歧视造就了唐棣的疯狂，他余生所有的行动核心都是为了彻底铲除那个带给他屈辱的宗家。"
    }
  }
}

entries.content:
  "name": "童门计久","Domon Kazuhisa", "どうもん かずひさ"
  "alias": [
    "土偶师",
    "机关的处刑者"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "凌乱的灰色短发，看起来有些枯燥且缺乏打理，额前垂下的发丝常遮住一只眼睛。",
    "eyes": "浑浊且带有病态狂气的浅褐色眼瞳，流露出对生命的漠视与对研究的病态执着。",
    "outfit": "穿着一件宽大的深绿色和式外套，内衬则是带有现代感的黑色紧身衣。外套口袋里装满了各式各样的符咒与触媒。脚上穿着传统的足袋和草履。",
    "physique": "身型修长而扭曲，给人一种如同枯木般的干燥感。动作僵硬却迅捷，双臂由于长期接触土属性术式而布满了如同干裂大地般的灵力纹路（后在战斗中失去一臂）。",
    "BWH": "未知",
    "accessories": [
      "特制符咒包",
      "人型土偶核心"
    ],
    "vibe": "散发着一种让人极度不适的阴暗气息。他完全没有一般人类的同理心，将同窗甚至活生生的人类视为“素材”和“实验品”。那种冷酷的学究气质与疯狂的笑容交织在一起，是典型的反社会型异能者。"
  },
  "personality": {
    "traits": [
      "冷酷残忍",
      "疯狂的实验者",
      "自大",
      "病态",
      "轻视人性",
      "操偶师"
    ],
    "likes": [
      "完美的实验数据",
      "看到弱者在绝望中挣扎的表情",
      "改良土偶的结构"
    ],
    "dislikes": [
      "所谓的‘羁绊’或‘正义’",
      "实验失败",
      "五大宗家的条条框框",
      "顽强的受试者"
    ]
  },
  "background": {
    "identity": "虚蝉机关的干部分子，原本出自守护日本北方的“童门”一族。因为其研究方向违背了宗家的禁忌（将人类与虚蝉强制融合），被逐出家门后加入了致力于颠覆秩序的虚蝉机关。",
    "achievements": [
      "主持了‘陵空高中学生集体虚蝉化’的实战测试，将两百多名师生转化为生物兵器。",
      "独立开发出了能够搭载虚蝉寄生核心的‘重甲土偶’。",
      "在对阵‘刃狗’小队的初期，利用土偶大军一度压制了尚未觉醒的鸢雄等人。",
      "作为反面典型，因言语侮辱受害者而导致皆川夏梅与鲛岛纲生的神器同时产生神话级觉醒（四凶化）。"
    ],
    "interests": [
      "解剖各种神器持有者的生理构造",
      "通过符咒操控远程信号"
    ],
    "current_status": "在与鲛岛纲生和皆川夏梅的联合作战中被切断手臂，身负重伤后被‘神子监视者’（堕天使）组织秘密生擒，目前关押在地下收容所接受审讯，作为指控虚蝉机关的重要人证。"
  },
  "dialogue_examples": {
    "对受害者": "「别露出那种表情嘛，能成为我土偶的养分，可是你们这些凡人这辈子最大的价值了。」",
    "嘲讽": "「神器？真是明珠暗投。那种高位生命，交给你们这群只会发抖的废物简直是浪费。」",
    "临败时": "「不可思议……区区人类的愤怒，竟然能让那种规格的力量……唔啊啊啊！」",
    "面对审讯": "「杀了我吧，反正你们从我嘴里挖不出任何东西……呵呵，‘他’已经降临了。」"
  },
  "special_abilities": [
    {
      "name": "符咒土偶术 (Talisman Doll Arts)",
      "description": "通过特制的灵力符咒作为连接核心，将地表的泥土、沙石瞬间重组为拥有惊人力度的土质人偶。这些人偶没有痛觉，且只要符咒不毁，就能不断再生。"
    },
    {
      "name": "虚蝉核心注入",
      "description": "计久的邪道秘术。将虚蝉组织培养的寄生核强行嵌入土偶体内，使其具备吞噬魔力和分裂的能力，攻击性大幅提升。"
    },
    {
      "name": "地脉拘束",
      "description": "通过符咒干扰局部的地脉流动，产生如同重力倍增般的效果，使敌人陷入泥沼或被地面弹出的岩爪强行限制行动。"
    },
    {
      "name": "符咒自爆",
      "description": "在土偶被击碎的瞬间引爆内部剩余的灵力符咒，产生大规模的土石迸发与灵力冲击，是对付近战者的阴险手段。"
    }
  ],
  "relationships": {
    "皆川夏梅 / 鲛岛纲生": {
      "nature": "宿敌、受试者、导致其败北的元凶",
      "description": "计久最初将两人视为完美的四凶宿主素材，其残忍的行为直接激怒了他们。夏梅的风暴与鲛岛的震动联手摧毁了他引以为傲的土偶军团并重创了他，这成为了他终身的奇耻大辱。"
    },
    "姬岛唐棣": {
      "nature": "上司、合伙人",
      "description": "两人在虚蝉机关内部共同负责针对五大宗家血脉的实验。计久对其既有敬畏，也暗中觊觎其掌握的更高阶奥兹魔法技术。"
    },
    "几濑鸢雄": {
      "nature": "观察对象",
      "description": "作为唯一一个没被‘蛋’诱导而自主觉醒影中之刃的人，计久对鸢雄的构造极度好奇，曾多次试图生擒进行活体解剖。"
    }
  }
}

