    "战斗宣言": "「在紫色的余烬中跳舞吧！这就是魔女的洗礼！」",
    "恶意嘲讽": "「你们那副正义凛然的样子，真是让我想吐呢。」"
  },
  "special_abilities": [
    {
      "name": "紫炎祭主的行刑台 (Incinerate Anthem)",
      "description": "十三种神灭具之一。能产生专门针对灵体与契约的紫色“裁决之炎”。华波加继承后，使其更具流动性，能够化为火海或精密的火焰陷阱，任何触碰到紫炎的事物都会受到灵魂层面的灼烧。"
    },
    {
      "name": "东国秘术：紫炎连锁",
      "description": "通过特定的魔法轨迹连接多处火焰，形成巨大的切割网，或是将敌人困在不断收缩的火环之中。"
    }
  ],
  "relationships": {
    "雅乌库斯塔": {
      "nature": "师徒、继承与取代",
      "description": "虽然是其徒弟，但在雅乌库斯塔死后表现出的冷静与果断证明了华波加并无多少敬意，更多的是将其作为获取力量的台阶。"
    },
    "撒坦耶尔": {
      "nature": "盟友、相互利用",
      "description": "共同组建祸之团，利用对方的技术与资源来实现魔女的野心。"
    }
  }
}

