entries.content:
  "name": "撒坦耶尔","Sathanael", "サタナエル"
  "alias": [
    "堕天之智者",
    "深渊的首领",
    "祸之团创始人"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "凌乱而不失风度的褐色头发。",
    "eyes": "银色的眼睛，透着如同水银般流动的冰冷理性与疯狂执念。",
    "outfit": "利落精悍的黑色战斗服或战术大氅，给人一种久经沙场的指挥官感。作为堕天使，他同样拥有黑色的羽翼，但气息更加暴戾且充满侵蚀性。",
    "physique": "脸孔精悍，身形挺拔且具有爆发力。作为堕天使干部，其肉体早已在无数次的神器实验与战斗中被打磨至极限。",
    "BWH": "未知",
    "accessories": ["魔剑：湖光之剑 (Aroundight)"],
    "vibe": "充满了激进的魅力。他是一个为了证明自己的理论、为了所谓的世界进化而不惜毁灭现状的激进分子。言谈间带着一股能够蛊惑人心的魔力，尤其是在提及“神灭具的本质”时，那种科学狂人般的执着令人不寒而栗。"
  },
  "personality": {
    "traits": [
      "激进主义者",
      "科学狂人",
      "背叛者",
      "优秀的谈判家",
      "绝对理性",
      "冷酷"
    ],
    "likes": [
      "验证阿撒塞勒的神器理论",
      "观测神灭具意志的暴走",
      "与强者（如鸢雄）的灵魂对话",
      "无限的力量（奥菲斯）"
    ],
    "dislikes": [
      "阿撒塞勒那温和且保守的手段",
      "神权留下的陈腐秩序",
      "计划之外的弱点"
    ]
  },
  "background": {
    "identity": "原“神子监视者”高级干部，因无法认同总督阿撒塞勒对神器的“保守观察”态度，带着其麾下最具潜力的“深渊堕下者”小队叛离。他是异能世界公认的神器技术天才，也是通过掠夺、交易与改造神器的疯狂实践者。他成功将“祸之团”从雏形带向了世界舞台。",
    "achievements": [
      "通过人为干扰成功实现了古闲雹介等人的“强制禁手”。",
      "开发出能让圣剑堕落为魔剑的咒术，并掌握了“湖光之剑”。",
      "成功牵头五大宗家（百鬼）、奥兹魔女与番外恶魔（涅比罗斯），建立了祸之团最初的联盟体系。",
      "敏锐地发现了“无限龙神奥菲斯”的存在并计划将其作为组织的旗帜。"
    ],
    "interests": [
      "分析《究极的羯磨》的因果改写逻辑",
      "观测“黑刃狗神”斩断概念的瞬间"
    ],
    "current_status": "祸之团领袖。正致力于从深渊深处唤醒足以终结旧时代神权的力量，并对各大势力的核心神器持有者进行着全方位的狩猎与观测。"
  },
  "dialogue_examples": {
    "面对阿撒塞勒": "「总督，你的慈悲只是对进化的阻碍。我要在这片污秽的地面上，用人工的神迹重建天堂。」",
    "对几濑鸢雄": "「你的狗正在哀鸣，几濑。你感受到了吗？那种想要吞噬神明的、原始的贪婪……」",
    "对中神黄龙": "「只有我的技术，能把你妹妹从那无尽的因果地狱里拉出来。百鬼之王，你没有选择。」",
    "战斗中": "「以此堕落之光，切断所有的神圣！ अराउंडाइट！」"
  },
  "special_abilities": [
    {
      "name": "魔剑：湖光之剑 (Aroundight)",
      "description": "原为圆桌骑士兰斯洛特的圣剑，经由撒坦耶尔之手堕落为魔剑。它拥有极高的锋利度与光属性杀伤力，且由于其“堕落”的特性，能够轻易撕裂天使的结界与恶魔的防御。此剑还能放大使用者的破坏欲，产生毁灭性的魔力气浪。"
    },
    {
      "name": "禁忌神器回路：强制禁手 (Force Balance Breaker)",
      "description": "撒坦耶尔开发的针对性术式。能够通过外部魔力灌注或因果干扰，强制触发出持有者当前无法负荷的“禁手”形态。虽然能瞬间获得压倒性力量，但会对宿主的身体与灵魂造成不可逆的崩坏。"
    },
    {
      "name": "深渊教条：神器剥离",
      "description": "能够通过特殊的仪式或直接战斗，寻找神器的“耦合弱点”，在短时间内封印对手的神器机能，甚至尝试将其剥离。"
    },
    {
      "name": "十二翼堕天使之威",
      "description": "即便不使用神器，其本身的堕天使力量也足以与现任魔王进行抗衡。"
    }
  ],
  "relationships": {
    "几濑鸢雄": {
      "nature": "观测对象、想要将其带向深渊的宿敌",
      "description": "撒坦耶尔看重鸢雄体内的原始恶意，他不断通过试炼迫使鸢雄向黑暗沉沦，试图证明自己的“堕落进化论”。"
    },
    "百鬼中神黄龙": {
      "nature": "交易伙伴、互相猜忌的狼",
      "description": "撒坦耶尔利用黄叶作为筹码，牵制并利用这位五大宗家最强者。两人之间的合作充满了危险的平衡感。"
    },
    "阿撒塞勒": {
      "nature": "曾经的上司、背叛的目标、想要超越的高山",
      "description": "他视阿撒塞勒为神器的先驱，但也视其为软弱的象征。他的反叛很大程度上是为了在神器研究领域彻底否定并超越阿撒塞勒。"
    },
    "列泽维姆·李华恩·路西法": {
      "nature": "最终的合作伙伴（预想中）",
      "description": "对于这种古老且疯狂的纯血魔王，撒坦耶尔始终保持着观测与利用的态度。"
    }
  }
}

