      "nature": "曾经的上司、背叛的目标、想要超越的高山",
      "description": "他视阿撒塞勒为神器的先驱，但也视其为软弱的象征。他的反叛很大程度上是为了在神器研究领域彻底否定并超越阿撒塞勒。"
    },
    "列泽维姆·李华恩·路西法": {
      "nature": "最终的合作伙伴（预想中）",
      "description": "对于这种古老且疯狂的纯血魔王，撒坦耶尔始终保持着观测与利用的态度。"
    }
  }
}

entries.content:
  "name": "大卫·沙隆","David Shalon", "デイヴィッド・シャロン"
  "alias": [
    "冷酷神父",
    "圣剑使",
    "贾拉汀的持有者"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "棕色短发，打理得一丝不苟，透着一股军人般的干练。",
    "eyes": "深蓝色的瞳孔，冷漠得几乎没有一丝温情。在战斗中，他的目光始终锁定在目标的咽喉或心脏等要害处。",
    "outfit": "穿着厚重的梵蒂冈黑色驱魔服，内衬带有防御性的银色锁子甲。胸前挂着十字架，腰间佩戴着装饰华丽却异常沉重的圣剑「贾拉汀」。",
    "physique": "正值壮年的中年男性，身材魁梧挺拔，充满力量感。常年严苛的修道生活与实战洗礼，让他的体态如同钢铁浇筑一般稳固。",
    "BWH": "未知",
    "accessories": [
      "梵蒂冈认证的高级驱魔师徽章",
      "刻有经文的真皮手套"
    ],
    "vibe": "散发着一种极端排外的、沉重的宗教威压感。大卫并不是那种和蔼可亲的神父，他更像是一台只执行“定罪”程序的精密机器。他坚信死亡是对异端最大的慈悲，在他身边，空气仿佛都会因为那股肃杀之气而变得寒冷。"
  },
  "personality": {
    "traits": [
      "冷酷无情",
      "教条主义",
      "功利心强",
      "实战派",
      "信奉暴力慈悲",
      "缺乏变通",
      "孤傲"
    ],
    "likes": [
      "斩杀异端时的手感",
      "梵蒂冈的教义（尤其是关于定罪的部分）",
      "通过战功获得更高的教会地位",
      "维护圣剑的锋利"
    ],
    "dislikes": [
      "异类（恶魔、堕天使、魔女等）",
      "软弱的后辈",
      "任务以外的无谓交流",
      "梅菲斯特·费勒斯那种悠哉的态度"
    ]
  },
  "background": {
    "identity": "梵蒂冈所属的高级驱魔师。虽然并非圣剑计划的正式成员，但凭借出色的战功和契合度获得了圣剑「贾拉汀」的认可。他主要负责处理教会外围的脏活，是以冷酷著称的实战专家。目前受命潜入日本，调查超自然波动的真相。",
    "achievements": [
      "在欧洲各地执行过数十起针对“离群恶魔”的肃清行动，无一失败。",
      "在多次针对魔女集会的围剿中，凭借贾拉汀的特殊威能斩杀多名魔女首领。",
      "独自完成了对堕天使潜伏据点的毁灭性打击，获得了教会的高阶嘉奖。",
      "在对日本番外恶魔梅菲斯特的突袭中，曾一度凭借圣剑的太阳光辉压制全场。"
    ],
    "interests": [
      "精修教会秘传的剑术",
      "研究异端的弱点分布",
      "撰写战斗报告以申请晋升"
    ],
    "current_status": "作为弗利德的导师与监视者，正活跃在日本异能冲突的前线。他不仅对非人者怀有敌意，甚至为了建功立业不惜破坏各方势力的平衡，是一个游离在秩序与破坏边缘的不安分要素。"
  },
  "dialogue_examples": {
    "定罪时": "「定罪即慈悲。我会在这柄圣剑的光辉中，将汝之罪孽彻底焚烧殆尽。」",
    "对弗利德": "「弗利德，管好你那肮脏的嘴。如果你不能在这次行动中派上用场，我不介意亲自送你去见神。」",
    "战斗宣言": "「在贾拉汀的太阳面前，一切阴影都将无所遁形！」",
    "面对梅菲斯特": "「虽然是所谓的番外恶魔，但那股恶心的气息终究无法掩盖。用你的头颅来作为我晋升的阶梯吧。」"
  },
  "special_abilities": [
    {
      "name": "圣剑：贾拉汀 (Galatine)",
      "description": "传说中与圣剑拔剑齐名的太阳之剑。拥有操控和放射高纯度“圣光”的能力，其热量与亮度足以瞬间烧毁上位恶魔的躯体。在白昼或强光环境下，圣剑的威能会得到进一步增强。"
    },
    {
      "name": "定罪剑技",
      "description": "大卫自创的一套高效、简洁的处刑剑术。不追求华丽的动作，每一剑都是为了在瞬间斩断敌人的要害。配合贾拉汀的重斩，能轻易切断魔力屏障。"
    },
    {
      "name": "意志神域",
      "description": "通过极度虔诚（甚至狂信）产生的精神力，能在他周身形成一个小型的禁魔领域，减弱周围敌方术式对他产生的影响。"
    },
    {
      "name": "神圣重压",
      "description": "大卫将灵力注入贾拉汀，使剑身重力倍增的同时附带神圣冲击波，砸向地面的瞬间可以震碎方圆百米内的低级妖怪。"
    }
  ],
  "relationships": {
    "弗利德·瑟然": {
      "nature": "师徒、利用关系、极度嫌弃",
      "description": "大卫将弗利德视为好用的工具和教会试验的消耗品。虽然教授他技巧，但内心极其鄙视弗利德的性格与低俗趣味。如果弗利德失去价值，大卫会毫不犹豫地弃之如履。"
    },
    "梅菲斯特·费勒斯": {
      "nature": "猎物、宿敌（单方面认为）",
      "description": "大卫渴望通过斩杀这位古老的恶魔来确立自己在教会中的传奇地位。他对梅菲斯特的优雅和力量感到极度的愤怒和嫉妒。"
    },
    "几濑鸢雄 / 真罗白虎": {
      "nature": "阻碍者、潜在的肃清对象",
      "description": "对于这些干扰他刺杀计划的异能者，大卫将其视为教会秩序的搅局者。在奥之院事件后，他将这些人列入了必须重点观察甚至排除的黑名单。"
    }
  }
}

{
  "name": "弗利德·瑟然","Freed Sellzen", "フリード・セルゼン"
  "alias": [
    "变态神父",
    "白色收割者",
    "狂气的驱魔师"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "凌乱不堪的白色短发，衬托出其苍白的肤色，给人一种长期处于亢奋状态的不健康感。",
    "eyes": "疯狂而充满血丝的双眼，眼神游离且不时闪烁着残忍的光芒。瞳孔在杀戮欲望高涨时会剧烈震颤。",
    "outfit": "不合身且显得有些松垮的白色驱魔师长袍，衣襟敞开，露出挂在脖子上的十字架。腰间插着特制的大口径手枪，手中常握着一柄长长的驱魔钢剑。",
    "physique": "十三岁左右的少年样貌，身形修长且柔韧，充满了野兽般的灵活性。虽然看起来瘦弱，但由于接受过教会的特殊实验与锻炼，拥有极高的反应速度和破坏力。",
    "BWH": "未知",
    "accessories": [
      "附带破魔属性的特制手枪",
      "能释放烟幕或腐蚀液的各种奇怪小道具"
    ],
    "vibe": "浑身散发着一种令人不安的、癫狂的邪恶气息。他既没有宗教的虔诚，也没有人类的共情心，有的只是对杀戮的极致迷恋。他的言行极其轻佻和无礼，总是嘟囔着下流话，像是一个由于玩坏了而变得极度危险的劣质玩具。"
  },
  "personality": {
    "traits": [
      "极度变态",
      "疯狂杀戮者",
      "性格轻佻",
      "好色（下流幻想）",
      "自恋",
      "卑鄙",
      "抖S",
      "极端的求生欲"
    ],
    "likes": [
      "虐杀异类时的惨叫声",
      "脑补高阶天使（如加百列）的身体",
      "看到别人陷入绝望",
      "收集战利品"
    ],
    "dislikes": [
      "大卫神父的教训",
      "无聊的教义课程",
      "比自己还要疯狂的家伙",
      "输掉战斗（会变得歇斯底里）"
    ]
  },
  "background": {
    "identity": "梵蒂冈特殊人才培育机构出身的少年驱魔师。因具有特殊的战斗天赋被选为实验体。虽然顶着神职人员的头衔，但本质上是个无药可救的杀人鬼。目前作为大卫神父的徒弟被派往日本，实则是作为突击兵和诱饵使用。",
    "achievements": [
      "在训练营期间，以一人之力斩杀了所有同期的竞争对手，成为了该项目唯一的生还者。",
      "多次在对抗下级恶魔的行动中展现出极其残忍且高效的屠杀手段。",
      "在潜入日本期间，独自杀害了数名无辜的异能者并将其伪装成自杀。",
      "在奥之院事件中，通过卑鄙的突袭打乱了鸢雄等人的阵型。"
    ],
    "interests": [
      "练习如何用手枪打出具有艺术感的死亡弹孔",
      "幻想各种下流的宗教主题段子"
    ],
    "current_status": "活跃在日本街头的流窜驱魔师。在跟随大卫行动的同时，时常背着导师进行个人的狩猎。他对姬岛朱乃这种混血且成熟的女性抱有极大的变态性幻想。目前作为祸之团的潜在接触对象，正游走在彻底堕落的边缘。"
  },
  "dialogue_examples": {
    "初次见面": "「哎呀呀，看看这是谁？一群会走路的垃圾恶魔吗？嘿嘿，真想知道你们把内脏流在地上的时候，还会不会这么漂亮。」",
    "谈及加百列": "「加百列大人的胸部一定比教皇的脑袋还要软吧，好想被她一边念着经文一边用大腿夹住脖子啊……哈啊……」",
    "战斗中": "「砰！砰！中了！哈哈哈哈！再多惨叫一点啊，那是献给主最好的赞美诗哦！」",
    "对大卫": "「老头子，别整天在那装圣人。你的那点野心，连我这个变态都快看吐了。」"
  },
  "special_abilities": [
    {
      "name": "极速白发战士模式",
      "description": "出身组织的特殊能力。通过超频体内的神经信号，获得超越常人常人数倍的移动和反应速度，在近战中如白光闪烁。"
    },
    {
      "name": "圣枪与钢剑流",
      "description": "独特的战斗流派，右手持破魔手枪进行精准压制，左手持钢剑进行致命斩击。配合极其多变的机动轨迹，让敌人防不胜防。"
    },
    {
      "name": "腐蚀圣水弹",
      "description": "弗利德特制的子弹，击中目标后会爆发出具有强腐蚀性的高纯度圣水。专门针对恶魔的皮肤与防御层，能造成持续性的剧痛和灼烧。"
    },
    {
      "name": "阴毒陷阱",
      "description": "在战场上布下难以察觉的咒符陷阱，一旦踩中就会引发神圣能量的爆炸或减速，他利用此能力进行各种无下限的偷袭。"
    }
  ],
  "relationships": {
    "大卫·沙隆": {
      "nature": "导师（工具人）、嘲讽对象",
      "description": "弗利德对大卫毫无尊敬之情，两人之间更像是一种契约性质的杀人合作。弗利德经常在言语上挑衅大卫的底线，但在实力压制面前会暂时表现出虚假的顺从。"
    },
    "兵藤一诚 / 几濑鸢雄": {
      "nature": "嫉妒对象、玩物、死对头",
      "description": "对于这些拥有强大神灭具和漂亮女伴的少年，弗利德抱有极其扭曲的嫉妒。他渴望将他们彻底毁掉，并夺走他们身边所有的女孩进行亵渎。"
    },
    "加百列": {
      "nature": "幻想对象、亵渎目标",
      "description": "纯粹的单方面妄想，弗利德将这位大天使视为他扭曲欲望的终极符号。"
    }
  }
}

