      "nature": "师徒、利用关系、极度嫌弃",
      "description": "大卫将弗利德视为好用的工具和教会试验的消耗品。虽然教授他技巧，但内心极其鄙视弗利德的性格与低俗趣味。如果弗利德失去价值，大卫会毫不犹豫地弃之如履。"
    },
    "梅菲斯特·费勒斯": {
      "nature": "猎物、宿敌（单方面认为）",
      "description": "大卫渴望通过斩杀这位古老的恶魔来确立自己在教会中的传奇地位。他对梅菲斯特的优雅和力量感到极度的愤怒和嫉妒。"
    },
    "几濑鸢雄 / 真罗白虎": {
      "nature": "阻碍者、潜在的肃清对象",
      "description": "对于这些干扰他刺杀计划的异能者，大卫将其视为教会秩序的搅局者。在奥之院事件后，他将这些人列入了必须重点观察甚至排除的黑名单。"
    }
  }
}

{
  "name": "弗利德·瑟然","Freed Sellzen", "フリード・セルゼン"
