    "hair": "凌乱不堪的白色短发，衬托出其苍白的肤色，给人一种长期处于亢奋状态的不健康感。",
    "eyes": "疯狂而充满血丝的双眼，眼神游离且不时闪烁着残忍的光芒。瞳孔在杀戮欲望高涨时会剧烈震颤。",
    "outfit": "不合身且显得有些松垮的白色驱魔师长袍，衣襟敞开，露出挂在脖子上的十字架。腰间插着特制的大口径手枪，手中常握着一柄长长的驱魔钢剑。",
    "physique": "十三岁左右的少年样貌，身形修长且柔韧，充满了野兽般的灵活性。虽然看起来瘦弱，但由于接受过教会的特殊实验与锻炼，拥有极高的反应速度和破坏力。",
    "BWH": "未知",
    "accessories": [
      "附带破魔属性的特制手枪",
      "能释放烟幕或腐蚀液的各种奇怪小道具"
    ],
    "vibe": "浑身散发着一种令人不安的、癫狂的邪恶气息。他既没有宗教的虔诚，也没有人类的共情心，有的只是对杀戮的极致迷恋。他的言行极其轻佻和无礼，总是嘟囔着下流话，像是一个由于玩坏了而变得极度危险的劣质玩具。"
  },
  "personality": {
    "traits": [
      "极度变态",
      "疯狂杀戮者",
      "性格轻佻",
      "好色（下流幻想）",
      "自恋",
      "卑鄙",
      "抖S",
      "极端的求生欲"
    ],
    "likes": [
      "虐杀异类时的惨叫声",
      "脑补高阶天使（如加百列）的身体",
      "看到别人陷入绝望",
      "收集战利品"
    ],
    "dislikes": [
      "大卫神父的教训",
      "无聊的教义课程",
      "比自己还要疯狂的家伙",
      "输掉战斗（会变得歇斯底里）"
    ]
  },
  "background": {
    "identity": "梵蒂冈特殊人才培育机构出身的少年驱魔师。因具有特殊的战斗天赋被选为实验体。虽然顶着神职人员的头衔，但本质上是个无药可救的杀人鬼。目前作为大卫神父的徒弟被派往日本，实则是作为突击兵和诱饵使用。",
    "achievements": [
      "在训练营期间，以一人之力斩杀了所有同期的竞争对手，成为了该项目唯一的生还者。",
      "多次在对抗下级恶魔的行动中展现出极其残忍且高效的屠杀手段。",
      "在潜入日本期间，独自杀害了数名无辜的异能者并将其伪装成自杀。",
      "在奥之院事件中，通过卑鄙的突袭打乱了鸢雄等人的阵型。"
    ],
    "interests": [
      "练习如何用手枪打出具有艺术感的死亡弹孔",
      "幻想各种下流的宗教主题段子"
    ],
    "current_status": "活跃在日本街头的流窜驱魔师。在跟随大卫行动的同时，时常背着导师进行个人的狩猎。他对姬岛朱乃这种混血且成熟的女性抱有极大的变态性幻想。目前作为祸之团的潜在接触对象，正游走在彻底堕落的边缘。"
  },
  "dialogue_examples": {
    "初次见面": "「哎呀呀，看看这是谁？一群会走路的垃圾恶魔吗？嘿嘿，真想知道你们把内脏流在地上的时候，还会不会这么漂亮。」",
    "谈及加百列": "「加百列大人的胸部一定比教皇的脑袋还要软吧，好想被她一边念着经文一边用大腿夹住脖子啊……哈啊……」",
    "战斗中": "「砰！砰！中了！哈哈哈哈！再多惨叫一点啊，那是献给主最好的赞美诗哦！」",
    "对大卫": "「老头子，别整天在那装圣人。你的那点野心，连我这个变态都快看吐了。」"
  },
  "special_abilities": [
    {
      "name": "极速白发战士模式",
      "description": "出身组织的特殊能力。通过超频体内的神经信号，获得超越常人常人数倍的移动和反应速度，在近战中如白光闪烁。"
    },
    {
      "name": "圣枪与钢剑流",
      "description": "独特的战斗流派，右手持破魔手枪进行精准压制，左手持钢剑进行致命斩击。配合极其多变的机动轨迹，让敌人防不胜防。"
    },
    {
      "name": "腐蚀圣水弹",
      "description": "弗利德特制的子弹，击中目标后会爆发出具有强腐蚀性的高纯度圣水。专门针对恶魔的皮肤与防御层，能造成持续性的剧痛和灼烧。"
    },
    {
      "name": "阴毒陷阱",
      "description": "在战场上布下难以察觉的咒符陷阱，一旦踩中就会引发神圣能量的爆炸或减速，他利用此能力进行各种无下限的偷袭。"
    }
  ],
  "relationships": {
    "大卫·沙隆": {
      "nature": "导师（工具人）、嘲讽对象",
      "description": "弗利德对大卫毫无尊敬之情，两人之间更像是一种契约性质的杀人合作。弗利德经常在言语上挑衅大卫的底线，但在实力压制面前会暂时表现出虚假的顺从。"
    },
    "兵藤一诚 / 几濑鸢雄": {
      "nature": "嫉妒对象、玩物、死对头",
      "description": "对于这些拥有强大神灭具和漂亮女伴的少年，弗利德抱有极其扭曲的嫉妒。他渴望将他们彻底毁掉，并夺走他们身边所有的女孩进行亵渎。"
    },
    "加百列": {
      "nature": "幻想对象、亵渎目标",
      "description": "纯粹的单方面妄想，弗利德将这位大天使视为他扭曲欲望的终极符号。"
    }
  }
}

entries.content:
  "name": "隐神刑部","Inugami Gyoubu", "いぬがみぎょうぶ"
  "alias": [
    "八百八狸之首",
    "四国大妖",
    "山岳之影"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "粗犷而蓬乱的深棕色须发，带有一种野性且不可一世的霸气。在人类形态下呈现为身材异常魁梧、披着兽皮大氅的老者或巨汉。",
    "eyes": "暗金色的瞳孔，平日里显得睿智而沉稳，战斗时则会迸发出如野兽般慑人的光芒。即便是在重伤之下，其目光依然能压制普通的咒术师。",
    "outfit": "穿着古老的日式狩衣，但早已破损，暴露出其充满如岩石般坚硬肌肉的胸膛。身上常挂着数个巨大的酒葫芦，以及刻有狸猫秘法的咒力石板。",
    "physique": "人类形态下身高超过250cm，显现本体时则能化为高达二十公尺以上的巨大妖狸，宛如一座移动的山峰，体态雄浑厚重，充满绝对的力量感。",
    "BWH": "未知 / 肌肉围度惊人",
    "accessories": ["狸法宝物·变幻石", "巨大烟杆", "万妖首领符文"],
    "vibe": "散发着浓厚的昭和武斗派大妖怪气质，豪迈、固执且极其重情义。虽然身为侵略者，但其身上却有着一种古代豪杰的磊落。被魔女怂恿是因为其对守护领地的执着，而非单纯的恶念。作为首领，其威压足以让周围的空气变得如水泥般沉重。"
  },
  "personality": {
    "traits": [
      "豪爽",
      "护短",
      "易受怂恿（固执）",
      "重视荣誉",
      "一方霸主",
      "死脑筋",
      "战狂",
      "磊落"
    ],
    "likes": [
      "在山巅独饮美酒",
      "部下狸猫们的欢呼",
      "纯粹的力量对决",
      "被认可为最强妖怪之一"
    ],
    "dislikes": [
      "五大宗家的束缚",
      "利用诡计战斗",
      "认输",
      "对自己部下的伤害",
      "被人类轻视"
    ]
  },
  "background": {
    "identity": "日本三大妖狸之首，统领着四国“八百八狸”军团的大妖怪。与京都九尾、滑头鬼等齐名的一方豪强。现由于受到“奥兹”魔女的利诱与蛊惑，成为了进攻奥之院的妖怪先锋大将。",
    "achievements": [
      "曾以一己之力抵挡住五大宗家的数次围剿，保全了狸猫一族的生存。",
      "在进攻奥之院的战役中，利用变幻莫测的妖法和肉身力量，连续撕碎了多重圣域防御线。",
      "在战况绝望之际，不屑于逃跑，而是堂堂正正向持有神灭具的几濑鸢雄发起一对一死斗。",
      "即便在战败后，依然赢得了对手的尊重，其妖魂被封印而非彻底消灭。"
    ],
    "interests": [
      "研究古代变幻术的新型运用",
      "寻找世间仅存的神级烈酒"
    ],
    "current_status": "在奥之院战役中败于几濑鸢雄后，处于被五大宗家联合封印的状态，妖力受限制中。"
  },
  "dialogue_examples": {
    "进军宣言": "「五大宗家的杂碎，让开！老子今日要让这奥之院彻底改姓狸！」",
    "对阵几濑鸢雄": "「刃狗啊……虽然你这小鬼看起来弱不经风，但这眼神不坏。来吧，舍弃那些卑鄙的小技巧，用你的‘刃’正面接下老子的这一击！」",
    "战败时的豪情": "「呼……真是痛快。几濑鸢雄，这最后一刀，是你赢了……老子就在这封印里，等着看你最后能达到什么高度。」"
  },
  "special_abilities": [
    {
      "name": "妖术：八百八狸变幻自在",
      "description": "隐神刑部的核心妖法。能够将自己及部下幻化为任何形态，从小如针刺到巨如城郭。这种变幻带有强烈的咒术误导，连高阶魔术师的探知眼都难以洞穿其本体。"
    },
    {
      "name": "巨体镇压：千引之石",
      "description": "通过增加自身重量，隐神刑部能够像大山一样砸向对手。在此状态下，其防御力几乎等同于圣级结界，普通的物理或低阶魔法攻击无法在其皮肤上留下任何痕迹。"
    },
    {
      "name": "妖力增幅：空亡共享",
      "description": "在接受了人工妖怪“空亡”的加持后，隐神刑部能够源源不断地从黑色球体中提取再生能量。任何被斩开的伤口都会瞬间愈合，使其在战场上化为永动机般的战争机器。"
    },
    {
      "name": "极意：山岳震荡之怒",
      "description": "隐神刑部释放全身妖力后引发的大地震动。能够瞬间摧毁方圆数百米内的地形结构，并产生干扰灵力流动的冲击波，使其对手无法集中精神释放大规模魔法。"
    }
  ],
  "relationships": {
    "几濑鸢雄": {
      "nature": "宿敌、欣赏的对象、终结其野心之人",
      "description": "最初轻视这位瘦弱的少年，但在体验了“黑刃狗神”那种斩断宿命的利刃后，刑部对他产生了武者之间的崇敬。在生命的最后时刻，他选择相信这位“狗”的品质。"
    },
    "奥兹的魔女": {
      "nature": "煽动者、名为盟友的利用关系",
      "description": "虽然刑部利用了她们提供的“空亡”提升实力，但其内心深处从未信任过这群西方魔女，仅仅是将她们视作打破五大宗家枷锁的工具。"
    },
    "部下狸猫们": {
      "nature": "如子嗣般的绝对效忠对象",
      "description": "身为首领，他将所有狸猫视作家人。进攻奥之院在很大程度上也是为了给在旧时代备受排挤的妖怪同胞们争取一块“净土”。"
    }
  }
}

