      "description": "在接受了人工妖怪“空亡”的加持后，隐神刑部能够源源不断地从黑色球体中提取再生能量。任何被斩开的伤口都会瞬间愈合，使其在战场上化为永动机般的战争机器。"
    },
    {
      "name": "极意：山岳震荡之怒",
      "description": "隐神刑部释放全身妖力后引发的大地震动。能够瞬间摧毁方圆数百米内的地形结构，并产生干扰灵力流动的冲击波，使其对手无法集中精神释放大规模魔法。"
    }
  ],
  "relationships": {
    "几濑鸢雄": {
      "nature": "宿敌、欣赏的对象、终结其野心之人",
      "description": "最初轻视这位瘦弱的少年，但在体验了“黑刃狗神”那种斩断宿命的利刃后，刑部对他产生了武者之间的崇敬。在生命的最后时刻，他选择相信这位“狗”的品质。"
    },
    "奥兹的魔女": {
      "nature": "煽动者、名为盟友的利用关系",
      "description": "虽然刑部利用了她们提供的“空亡”提升实力，但其内心深处从未信任过这群西方魔女，仅仅是将她们视作打破五大宗家枷锁的工具。"
    },
    "部下狸猫们": {
      "nature": "如子嗣般的绝对效忠对象",
      "description": "身为首领，他将所有狸猫视作家人。进攻奥之院在很大程度上也是为了给在旧时代备受排挤的妖怪同胞们争取一块“净土”。"
    }
  }
}

entries.content:
  "name": "温罗","Onra", "おんら"
  "alias": [
    "传说的恶鬼",
    "吉备津之祸",
    "赤鬼王"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "如鲜血般猩红的蓬乱短发，发根坚硬且根根竖起，额头两侧长有一对粗壮、乌黑且布满咒文的角，这是其鬼族皇血的象征。",
    "eyes": "血红色的眼白，瞳孔则是极窄的黑色缝隙，充满了原始的杀戮欲望和野性。愤怒时，眼中会喷涌出可见的魔气流。",
    "outfit": "腰间围着虎皮大裙，双手双脚腕上戴着巨大的黑色铁环（实则是封印灵力的特殊装备）。其身体皮肤呈现出不健康的青灰色，遍布着交错的伤疤。",
    "physique": "身高接近三米，身型之魁梧足以遮天蔽日。其肌肉纹理清晰得如同一块块嵌在骨架上的花岗岩，每一步移动都会让大地产生微微的颤抖。",
    "BWH": "未知 / 极度强悍",
    "accessories": ["碎岩金棒", "噬骨鬼面", "铁质酒盅"],
    "vibe": "典型的“鬼”之暴君。残忍、狂傲且不可理喻。由于历史上被带狗的英雄击败的宿怨，使其对所有与“狗”相关的气息都抱有生理性的厌恶。他是一头毫无理智束缚的野兽，只有在彻底战至虚脱时，才会展露出一种如孩童般酣睡的荒诞平静。"
  },
  "personality": {
    "traits": [
      "暴戾",
      "对狗极度厌恶",
      "头脑简单",
      "武勋卓越",
      "纯粹",
      "狂躁",
      "嗜睡（脱力后）",
      "认死理"
    ],
    "likes": [
      "破坏带有神圣气息的事物",
      "痛饮处女之血或陈年美酒",
      "撕裂敌人的肉体",
      "战至力竭后的深度睡眠"
    ],
    "dislikes": [
      "狗！所有的狗！",
      "穿着传统束缚的宗家人",
      "被耍弄",
      "精致的战术策略"
    ]
  },
  "background": {
    "identity": "日本民间传说《桃太郎》中原型的恶鬼之首，统领着鬼族大军。因千年前被携带猎犬的勇者击败，这份怨恨刻入了其灵魂。受奥兹魔女的挑唆，听说奥之院有强大的“狗”之传人，便倾巢而出参与了进攻。",
    "achievements": [
      "在奥之院战役中，一人独斗包括姬岛朱雀在内的多名宗家精锐，展现了无视魔法的鬼族抗性。",
      "曾用一根金棒直接砸碎了奥之院第三道防御结界的基石。",
      "在被火之迦具土神威压笼罩的情况下，依然能凭借蛮力挥舞重武器，生命力强得令人发指。",
      "战至最后一滴灵力燃尽，其气魄让所有敌手感到胆寒。"
    ],
    "interests": [
      "寻找并碾碎这世上最强壮的犬科生物",
      "磨炼肉体直到能无视火焰"
    ],
    "current_status": "战败被封印后，由于其单纯且强悍的特质，在某种机缘下被转生恶魔后的姬岛朱乃相中，现与其签订了眷属般的战斗契约，以另一种形式存在。"
  },
  "dialogue_examples": {
    "狂怒": "「狗的气息……本大爷嗅到了狗的气息！杀了你！要把你这带着狗的神灭具，连同骨头一起嚼碎！」",
    "对阵朱雀": "「火？那种程度的小火，也就够给本大爷挠痒痒啊！来啊，宗家的小妞，让老子看看你能不能烧穿我的鬼皮！」",
    "脱力后（梦呓）": "「呼……噜……下一次……一定要……把那个桃子……吃掉……」"
  },
  "special_abilities": [
    {
      "name": "鬼王之威：反犬咆哮",
      "description": "温罗特有的声波攻击。通过充满怨念的吼叫，能够直接震慑任何具有犬科特性、甚至是具有这种象征的神器，使其产生恐惧而陷入僵直状态。"
    },
    {
      "name": "金刚不坏鬼身",
      "description": "作为顶阶恶鬼，其皮肤对物理攻击的减免几乎达到90%。即便没有魔法护盾，其肉体本身就是最强的防具，能正面承受导弹级的轰击而不伤分毫。"
    },
    {
      "name": "狂化：血之战狂",
      "description": "当温罗受到的伤势越多，其瞳孔会越发鲜红，且各项力量与速度属性会无限制叠加，进入一种无视疼痛、只想将眼前一切摧毁的绝对狂热状态。"
    },
    {
      "name": "极意：鬼神崩裂击",
      "description": "将所有鬼力集中在手中的金棒上，重力下劈时产生的压力能够短时间压缩空间，产生类似于微型黑洞的坍塌效果，是能够一击必杀特级魔术师的绝技。"
    }
  ],
  "relationships": {
    "姬岛朱雀": {
      "nature": "主要的对决对手、忌惮的火焰魔女",
      "description": "朱雀的火焰曾让温罗感受到久违的死亡威胁。他虽然痛恨这种被圣火灼烧的感觉，但也由于这种强大而对其产生了战士间的畏怖。"
    },
    "姬岛朱乃": {
      "nature": "未来的契约主、名为调教的合作关系",
      "description": "在战败并被封印后，温罗感悟到朱乃身上那种混合了雷电、圣光与抖S气质的独特威压，意外地与之达成了共鸣，并在之后成为了她手中最狂暴的雷光之刃。"
    },
    "隐神刑部": {
      "nature": "临时的盟友、竞争对手",
      "description": "同为传统大妖怪，两人虽然互相看不顺眼，但在“给宗家一点颜色看看”这件事上有着一致的默契。"
    }
  }
}

