entries.content:
  "name": "空亡","Utsuho", "うつほ"
  "alias": [
    "人工灾祸",
    "祸之卵",
    "伪太阳"
  ],
  "appearance": {
    "gender": "无",
    "hair": "无（呈现为物质形态）",
    "eyes": "无（通过表面的暗淡光点感知周围）",
    "outfit": "无。",
    "physique": "形态极其不稳定的黑色球体，表面流转着如同浓稠沥青般的妖气。其直径可以随吸纳伤势的多少而在几米到数十米之间波动，给人一种不详的吞噬感。球体内部隐约可见无数扭曲的符文。而在天空中漂浮时，其视觉效果如同一轮漆黑的、散发着寒意的死之太阳。",
    "BWH": "无",
    "accessories": [],
    "vibe": "没有生命情感的纯粹灾厄。它所到之处，空气会变得凝重且充满腥甜的铁锈味。与其说是妖怪，不如说是奥兹魔女利用某种禁忌技术制造的“因果修改装置”。它不散发杀意，却散发出一种虚无的饥饿感。"
  },
  "personality": {
    "traits": [
      "非人格化",
      "绝对忠诚（程序性）",
      "无限自我修复（被吞噬前）",
      "诡异的寂静",
      "因果干涉者",
      "伪装的母体"
    ],
    "likes": [
      "吸收痛苦与伤痕",
      "扩散妖气浓雾",
      "让秩序崩坏"
    ],
    "dislikes": [
      "高阶神性火焰（如火之迦具土）",
      "吞噬因果的虚空（如饕餮）"
    ]
  },
  "background": {
    "identity": "由奥兹国魔女联合“虚蝉机关”残部利用人工神器技术制造的复合型妖怪。其名字取自日本传说中最为不详的妖怪之名，意为“万物的终焉”。",
    "achievements": [
      "在奥之院攻防战中，作为妖怪大军的核心枢纽，使上千名狸猫与恶鬼获得了“不死身”般的持续作战能力。",
      "成功解析并反弹了数道由五大宗家长老联合释放的封印法术。",
      "在被火之迦具土神附着的影之刃大卸八块后，其核心依然能尝试聚拢并修复，展现了惊人的生命维度。",
      "作为一次性战略兵器，它几乎成功改写了妖怪一族的败亡宿命，直到遇见其天敌。"
    ],
    "interests": [
      "逻辑驱动：维持范围内妖怪的血条上限"
    ],
    "current_status": "已被几濑鸢雄彻底斩碎，碎块被七泷诗求子的神器“小波”完全吞噬，在概念与物质层面上已彻底消失。"
  },
  "dialogue_examples": {
    "运行音": "「……呜……呼……响应……伤痕……消散……」",
    "破灭时": "「逻辑……中断……黑暗……被……吃掉了……」"
  },
  "special_abilities": [
    {
      "name": "能力：伤痕转移（伪不死）",
      "description": "空亡的核心异能。能实时感应范围内友军单位的受损情况，并瞬间将这些伤势抽离，转化为自身的膨胀体积。这使得受加持的妖怪即使受了致死伤也能维持全盛战力。"
    },
    {
      "name": "能力：灾厄反弹",
      "description": "能够吸收敌方的法术攻击并在其体内通过妖气增幅后再次反射。普通的元素魔法对空亡几乎只能起到充能作用。"
    },
    {
      "name": "妖气日蚀",
      "description": "空亡能够散发出大范围的黑色妖雾，遮蔽阳光并屏蔽任何神圣属性的感应。在雾中，人类及神官的感知力会被压制到零，而妖怪则会获得极大的增益。"
    },
    {
      "name": "由于空亡机制引发的“崩溃惩罚”",
      "description": "并非其主动技能。一旦空亡消失，其生前吸收并压制的所有伤势会瞬间、百分之百地回到原持有者身上，造成延迟性的肉体大崩盘。"
    }
  ],
  "relationships": {
    "隐神刑部": {
      "nature": "共生伙伴、核心驱动源",
      "description": "由于刑部的妖力最强，空亡与他的同步率最高，两者的契合让刑部在战场上几乎成为了真正无法被杀死的山之神。"
    },
    "奥兹的魔女": {
      "nature": "造物主、操纵者",
      "description": "空亡仅仅是她们投入战场的一个实验数据采集端，魔女们通过观察其在奥之院的表现，来完善后续的人工妖怪技术。"
    },
    "几濑鸢雄与小波": {
      "nature": "天敌、终结者",
      "description": "鸢雄的神之火破坏了空亡的再生逻辑，而诗求子的小波则从空间层面抹除了其复活的可能性。这对组合是空亡唯一无法应对的组合拳。"
    }
  }
}

