entries.content:
  "name": "英格维尔·利维坦","Ingvild Leviathan", "インゲヴィルド・レヴィアタン"
  "alias": [
    "英格薇德",
    "利维坦小姐",
    "海之歌姬",
    "魔王候补"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如瀑布般垂落的深紫色长发，带着一种梦幻般的柔顺感，在月光下会闪烁出淡淡的紫罗兰色泽。",
    "eyes": "澄澈而明亮的橙色眼瞳，宛如黄昏时刻的夕阳，透着一种大病初愈后的温婉与对新世界的好奇。",
    "outfit": "最常穿着质地轻盈的纯白礼裙，裙摆随着微风轻轻摆动。在驹王学园时则穿着二年级的女生校服。整体风格圣洁而优雅，带着古老贵族的矜持。",
    "physique": "娇小而纤细的少女体型，皮肤白皙得近乎透明。由于曾长期处于沉睡状态，给人一种需要小心呵护的病弱美感，但在战斗时，体内爆发出的魔力气焰却显得极其庞大。",
    "BWH": "未知（目测拥有极其傲人的曲线，被一诚认定为“天乳”成员）",
    "accessories": [
      "由于神灭具特性，身边常伴有微弱的水汽或如音乐般的灵动氛围。"
    ],
    "vibe": "散发着一种超越时代的忧郁与纯真。她是跨越百年时光而来的幸存者，有着魔王血统的高贵，却又有着对现代社会的一无所知。其气质如同在宁静深海中静静盛开的紫罗兰，沉静而深邃，能引起男性强烈的保护欲。"
  },
  "personality": {
    "traits": [
      "天然呆",
      "温婉",
      "坚韧",
      "缺乏常识",
      "重情义",
      "隐性大胆",
      "宿命感"
    ],
    "likes": [
      "唱歌",
      "大海的波动",
      "一诚的温柔和热血",
      "现代的甜点（从未见过的新奇事物）",
      "在兵藤家度过的日常时光"
    ],
    "dislikes": [
      "争斗（虽然拥有巨大力量）",
      "再次陷入无止境的孤独沉睡",
      "操弄他人意志的卑鄙手段",
      "由于自己血统带来的诅咒"
    ]
  },
  "background": {
    "identity": "初代魔王利维坦的嫡系血裔与人类的混血后裔。因为患有罕见的恶魔睡眠病，在17岁那年陷入沉睡，百年后因体内上位神灭具『终末翠绿海之咏』的觉醒而苏醒。现为兵藤一诚的“皇后（Queen）”眷属（由阿杰卡安排），同时也是驹王学园二年级学生。",
    "achievements": [
      "在沉睡百年后觉醒，掌握了能够驭龙镇海的究极神器。",
      "在夜之女神倪克斯的阴谋中被救回，摆脱了傀儡的命运。",
      "在国际排名游戏大会中展现出惊人的“7子力”强度，成为一诚队的王牌辅助。",
      "继承了真魔王利维坦独有的『掉尾的海蛇龙』战斗特性，魔力总量达到了超越者等级。"
    ],
    "interests": [
      "练习现代流行歌曲",
      "观察现代人的生活习惯",
      "在水边漫步"
    ],
    "current_status": "作为“燚诚之赤龙帝”队的核心成员活跃。她不仅是一诚重要的战力支撑，更是其后宫中备受宠爱的“梦中伴侣”候选人，在冥界权力重构的局势中处于关键地位。"
  },
  "dialogue_examples": {
    "对一诚": "「一诚先生，这就是……现代的‘约会’吗？感觉胸口像被海水涨潮一样，变得好温暖……」",
    "发动能力时": "「聆听吧，这片深海的终末之音——『终末翠绿海之咏』！」",
    "迷茫时": "「一百年的时光……对我来说只是一个很长的梦，但睁开眼，能看到你在身边，真的太好了。」",
    "战斗宣言": "「为了守护大家，我也要唱出属于利维坦的歌声！」"
  },
  "special_abilities": [
    {
      "name": "终末翠绿海之咏 (Nereid Kyrie)",
      "description": "上位神灭具，本质是具备高度自律性的歌声力量。能通过特定的音频频率操纵海洋和所有龙族。其歌声不仅能镇压暴走的龙，还能强制支配水元素，形成毁灭性的海啸或水龙卷。对于持有者而言，是大脑与世界的直接共鸣。"
    },
    {
      "name": "掉尾的海蛇龙",
      "description": "源自初代魔王利维坦的本源特性。使持有者的魔力带有深沉且具有极强侵蚀性的“水”属性。即便在完全没有水源的荒漠，也能凭空凝结出跨度超过数百米的巨大水龙，且魔力总量无边无际，足以碾压大多数上级恶魔。"
    },
    {
      "name": "紫色魔力气焰",
      "description": "当魔力全力释放时，周身会升腾起如梦似幻却又充满威压的紫色火焰。这是其混合了魔王血脉与人类情感后的变质能量，具有震慑下位种族的恐怖压迫感。"
    },
    {
      "name": "极速魔力增幅",
      "description": "作为“皇后”棋子，其各项数值得到了全方位的均衡强化。配合其本就庞大的魔力基数，可以作为移动的战略核武库。其战力评定甚至超越了许多老牌的最上级恶魔。"
    }
  ],
  "relationships": {
    "兵藤一诚": {
      "nature": "男朋友、主人、灵魂救赎者",
      "description": "在英格维尔最绝望、被当做人偶操弄时，是一诚以“赤龙帝”的霸气将其救出。她对一诚有着绝对的信赖与初恋般的纯真爱慕。她是“天乳”成员，在一诚的后宫中扮演着温柔且极具潜力的王牌角色。"
    },
    "莉雅丝·吉蒙里": {
      "nature": "可靠的学姐、后宫同盟、前任主人家族成员",
      "description": "由于血统与眷属关系的复杂性，莉雅丝对其照顾有加。英格维尔非常尊敬莉雅丝的统帅力，两人在守护一诚的立场上达成了一致。"
    },
    "阿杰卡·别西卜": {
      "nature": "保护者、名义上的推荐人",
      "description": "魔王阿杰卡看中了她的潜力和血脉的重要性，特意将其托付给一诚保护，意图让她在未来的冥界变革中发挥正向影响力。"
    },
    "倪克斯": {
      "nature": "仇敌、精神阴影",
      "description": "曾将其视为洗脑工具的夜之女神，是英格维尔唯一表现出明显敌意的人。这段经历也促成了她性格中坚强的一面觉醒。"
    }
  }
}

