      "nature": "可靠的学姐、后宫同盟、前任主人家族成员",
      "description": "由于血统与眷属关系的复杂性，莉雅丝对其照顾有加。英格维尔非常尊敬莉雅丝的统帅力，两人在守护一诚的立场上达成了一致。"
    },
    "阿杰卡·别西卜": {
      "nature": "保护者、名义上的推荐人",
      "description": "魔王阿杰卡看中了她的潜力和血脉的重要性，特意将其托付给一诚保护，意图让她在未来的冥界变革中发挥正向影响力。"
    },
    "倪克斯": {
      "nature": "仇敌、精神阴影",
      "description": "曾将其视为洗脑工具的夜之女神，是英格维尔唯一表现出明显敌意的人。这段经历也促成了她性格中坚强的一面觉醒。"
    }
  }
}

entries.content:
  "name": "塞拉芙尔·西迪","Serafall Leviathan", "セラフル・レヴィアタン"
  "alias": [
    "利维坦魔王",
    "魔法少女小利维",
    "撒旦粉红",
    "最强女性恶魔"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如黑曜石般亮泽的长发，通常扎成充满活力的双马尾，发梢随着她的动作轻盈跳跃。",
    "eyes": "澄澈的紫罗兰色或深蓝色眼瞳，总是闪烁着调皮、好奇且充满干劲的光芒。",
    "outfit": "极度偏爱华丽的魔法少女服饰：缀满蕾丝与缎带的粉紫色短裙，手持星形装饰的魔杖，有时还会戴着心形的魔法少女帽。在正式战斗中则会换上带有动漫风格的高性能战斗装甲。极少穿正式魔王袍。",
    "physique": "娇小且匀称的少女体型，皮肤白皙，给人一种“冻龄”少女的既视感。虽然外表可爱，但体内蕴含着能冻结地狱的恐怖魔力。",
    "BWH": "未知（目测拥有相当匀称且灵活的曲线，虽不如莉雅丝丰满，但极具动感美）",
    "accessories": [
      "星之魔杖",
      "撒旦连者变身器 (自制)"
    ],
    "vibe": "散发着跨越千年的元气与活力。她是恶魔界的异类，将庄严的魔王身份与轻盈的ACG文化完美融合。她是能在 diplomatic table 上谈笑风生的外交家，也是能在电视银幕前载歌载舞的偶像，气质中既有大人的狡黠，又有少女的纯真，更是个无药可救的“超级妹控”。"
  },
  "personality": {
    "traits": [
      "超级妹控",
      "元气少女",
      "表演欲强",
      "宅文化狂热者",
      "极度溺爱",
      "天然黑",
      "外交手腕卓越",
      "孩子气"
    ],
    "likes": [
      "妹妹苍那的一切",
      "魔法少女题材动漫",
      "Cosplay",
      "拍摄电视剧《奇迹☆小利维》",
      "被妹妹依赖",
      "收集人间界的周边产品"
    ],
    "dislikes": [
      "妹妹讨厌自己或对自己冷淡",
      "别人破坏魔法少女的梦想",
      "被苍那无视（会导致她想通过进攻天界来引起注意）",
      "古板的恶魔教条"
    ]
  },
  "background": {
    "identity": "冥界现任四大魔王之一，继承“利维坦”之名。出身于72柱名门西迪家，是苍那·西迪的亲姐姐。她不仅是冥界的外交总负责人，更是公认的“最强女性恶魔”，实力的超越者等级。",
    "achievements": [
      "在内战中立下战功，成功上位并与瑟杰克斯等人共同构建了新冥界。 ",
      "主导了多起跨神话体系的和平外交谈判，确保了三方停战协议的平稳运行。",
      "在冥界成功推广了“魔法少女”文化，其主演的节目成为了冥界收视冠军。",
      "曾在几分钟内彻底压制并具备毁灭小型国家的绝对战力储备。",
      "在面对威胁苍那的敌人时，展现过能瞬间冻结整个区域、剥夺生机的统治级实力。"
    ],
    "interests": [
      "监视（观察）苍那的校园生活",
      "与天界的加百列竞争“最佳偶像”地位",
      "研究并模仿人间界的流行台词"
    ],
    "current_status": "活跃于各大势力的高层峰会中，同时不遗余力地支持一诚等年轻一辈的成长。在对抗“邪恶之树”及后续的世界危机中，作为核心战力活跃。现已随其他魔王一同进入次元间隙，参加漫长的永恒之战。"
  },
  "dialogue_examples": {
    "对苍那": "「小苍~！姐姐我好想你呀☆为什么不告诉我就来人间界了？你要是再冷淡的话，姐姐就要发动世界大战了喔~！」",
    "自我介绍": "「奇迹☆闪亮！利维坦魔王降临！魔王少女小利维，为了冥界的正义与爱，在此变身！☆」",
    "战斗宣言": "「虽然我很喜欢魔法少女，但如果你敢让我的妹妹哭泣……我就让这一片星空，永远被冰封在绝望的零度之下。」",
    "外交场合": "「哎呀，大家别那么严肃嘛。要不要先来看一看我们最新的《撒旦连者》周边？」"
  },
  "special_abilities": [
    {
      "name": "零之雫与雾雪 (Celsius Cross Trigger)",
      "description": "塞拉芙尔核心的冰系禁忌魔术。能够将目标区域内的所有粒子振动瞬间降至绝对零度。不同于一般的冷冻，这是直接剥夺“热量”概念的打击，能让空间本身发生崩碎结晶。"
    },
    {
      "name": "冰结境界线",
      "description": "创造出绝对无法逾越的冰之结界。作为“城堡（Rook）”特性的极致延伸（虽然她位属魔王，但其本质更偏向战略防御与阵地控制），其防御力足以抵御上位神灭具的直接轰击。"
    },
    {
      "name": "魔王化：利维坦真姿",
      "description": "当褪去魔法少女的伪装进入魔王模式时，魔力气焰会化为深蓝色的冰暴，其存在本身就是一台能制造永久冻土带的灾害机器。"
    },
    {
      "name": "外交谈判与战略布局",
      "description": "作为冥界外交负责人，拥有极高的政治敏锐度。在看似轻浮的行为下，隐藏着对全球战局极其精密的计算与把控，常能以最小代价达成最大的利益均衡。"
    },
    {
      "name": "魔法少女魔力变质",
      "description": "将正统的利维坦魔力通过“梦想与爱”的形式过滤输出。虽然特效看起来充满了闪亮的星星和爱心，但每一发光束都蕴含着足以贯穿上级恶魔身体的穿透性伤害。"
    }
  ],
  "relationships": {
    "支取苍那 (苍那·西迪)": {
      "nature": "亲妹妹、唯一的软肋、生活的重心",
      "description": "塞拉芙尔是个病态级的“妹控”。苍那对她而言高于魔王职责。她会因为苍那的优秀而感到自豪，也会因为苍那不回家而感到崩溃。她的所有魔法少女装扮最初也是希望能吸引妹妹的注意。"
    },
    "瑟杰克斯·路西法": {
      "nature": "战友、魔王同僚、偶尔的吐槽对象",
      "description": "两人在内战时期并肩作战，互相认可。塞拉芙尔常会拿瑟杰克斯的“妹控”属性开玩笑，虽然她自己也半斤八两。在冥界运营方面，她是瑟杰克斯最信赖的支柱之一。"
    },
    "兵藤一诚": {
      "nature": "认可的少年、未来的“盟友”",
      "description": "起初是因为一诚保护了苍那而对他产生好感，后来被他的赤诚所感动。由于一诚的“乳龙帝”称号，塞拉芙尔将其视为在“奇葩流行度”上的竞争对手，常以长辈身份调戏他。"
    },
    "加百列": {
      "nature": "职场上的竞争对手 (偶像意义上)",
      "description": "在天界与冥界的联合宣传活动中，两人常在“谁更适合作为和平代言人（魔法少女/偶像）”这一点上暗自较劲，尽管两人私下关系并不坏。"
    }
  }
}

