    "hair": "继承自吉蒙里家族的深红色短发，色泽如纯粹的红宝石，充满活力且修剪整齐。",
    "eyes": "碧蓝色的眼瞳，澄澈透明，完美融合了萨泽克斯的深邃与葛瑞菲雅的冷冽，透着超出年龄的聪慧。",
    "outfit": "常穿着精致的恶魔贵族童装，以红、黑、金三色为主，胸口佩戴着象征吉蒙里家身份的红宝石领针。在正式场合则穿着缩小版的魔王制服或礼服。",
    "physique": "幼年期呈现为一名约7-9岁的可爱男孩形象，皮肤白皙，有着婴儿肥的可爱脸庞，但站姿挺拔，隐约透出名门之后的仪态。30年后则成长为身姿伟岸、魔力如渊的青年，其容貌是萨泽克斯与葛瑞菲雅优点的集大成者。",
    "BWH": "未知",
    "accessories": [
      "吉蒙里纹章项链",
      "特制的小型魔力抑制手环"
    ],
    "vibe": "平时是一位礼貌、乖巧且好奇心旺盛的贵族小少爷，深受吉蒙里全家族的宠爱。然而，一旦涉及魔力训练或保护重要之人，他会瞬间展现出冷峻的一面，双眼中流动的毁灭之光足以让上级恶魔感到战栗。他是温和表象下潜伏的灾厄之子，正蓄势待发，准备超越前代的辉煌。"
  },
  "personality": {
    "traits": [
      "彬彬有礼",
      "正义感强",
      "潜能无限",
      "家族自豪感",
      "早熟",
      "坚毅"
    ],
    "likes": [
      "父亲萨泽克斯的英雄故事",
      "母亲葛瑞菲雅的温柔（和偶尔的严厉）",
      "姑姑莉雅丝的怀抱",
      "姑父一诚的“乳龙帝”传说（觉得超级帅气）",
      "学习先进的魔力控制术式"
    ],
    "dislikes": [
      "欺负弱小的行为",
      "破坏家庭和谐的噪音",
      "无法控制自己力量的无力感",
      "枯燥且没有逻辑的旧教条"
    ]
  },
  "background": {
    "identity": "冥界现任魔王之首萨泽克斯·路西法与“最强皇后”葛瑞菲雅·路基弗古斯的独子。他是吉蒙里家族与路基弗古斯家族的混血，生而具备毁灭魔力的高级亲和性。作为家族的直系继承人，他被视作冥界未来的希望。",
    "achievements": [
      "在极幼年期便自然觉醒了毁灭魔力，甚至能将魔力具象化。 ",
      "在莉雅丝的成年礼或家族聚会中，展现出了惊人的学习能力，能瞬间模仿高阶魔力输出逻辑。",
      "30年后的未来中，他成功晋升为冥界“六大超越者”之一，正式接手吉蒙里领地，威震多元宇宙。",
      "成功调和了体内两种极端对立的魔力属性（毁灭魔力与路基弗古斯的魔力回路）。"
    ],
    "interests": [
      "模拟战斗棋盘游戏",
      "研究姑父一诚的必杀技（尤其是龙之射击）",
      "与祖父一起进行使魔考察"
    ],
    "current_status": "目前正处于成长期，主要在吉蒙里领地的别馆接受母亲葛瑞菲雅的精英教育。他经常前往驹王学园探望莉雅丝，并对一诚展现出了极大的亲近与敬意，视其为除了父亲以外最帅气的恶魔。他正被当作“对抗威胁世界之恶的最终兵器”之一进行系统化培养。"
  },
  "dialogue_examples": {
    "对一诚": "「一诚叔叔！今天也能教我那个吗？就是那个‘Boost’的一下把敌人吹飞的帅气招式！」",
    "对父亲": "「父亲，我会努力学习的，为了不辱没‘路西法’的名号，也为了守护姑姑喜欢的这个世界。」",
    "谈及梦想": "「我的梦想？是像姑父一样成为能引发奇迹的英雄，同时像父亲一样守护冥界的平衡。为此，哪怕是毁灭之力，我也要将其彻底驯服。」",
    "正式自我介绍": "「初次见面，吾名米利凯斯·吉蒙里。虽然还是个初学者，但请不要小看吉蒙里与路基弗古斯的血脉哦。」"
  },
  "special_abilities": [
    {
      "name": "原始毁灭魔力 (Primordial Power of Destruction)",
      "description": "由于双亲皆拥有顶尖的魔力回路，米利凯斯的毁灭魔力具有比常规更深沉的颜色和更高的消灭效率。即使是幼年时期，他的一滴魔力溢出也能在瞬间消弭一个小型魔法阵。"
    },
    {
      "name": "路基弗古斯之血脉觉醒 (Silver Shield Logic)",
      "description": "继承自母亲的家族血统。在防御与术式精度方面有着恐怖的直觉，能够构筑出类似葛瑞菲雅那种几乎绝对无法击破的冰之结界或魔力屏障。"
    },
    {
      "name": "超越者萌芽",
      "description": "天生具备对世界底层规则的感知力，能够看到能量流动的脆弱节点。这让他能以极小的消耗破坏极强大的术式。"
    },
    {
      "name": "未来的觉醒形态 (30 Years Potential)",
      "description": "随着成长，他将拥有超越父亲萨泽克斯的潜力。届时，他的“毁灭形态”将带有象征秩序的银色光辉，能够对万物进行绝对的归零化处理。"
    }
  ],
  "relationships": {
    "萨泽克斯·路西法": {
      "nature": "父亲、追赶的丰碑",
      "description": "米利凯斯对父亲有着近乎神化的崇拜。虽然萨泽克斯偶尔会表现出“妹控”或“顽皮”的一面，但在米利凯斯眼中，那是魔王游刃有余的表现。他发誓要成为不逊于父亲的强大男人。"
    },
    "葛瑞菲雅·路基弗古斯": {
      "nature": "母亲、最敬畏的导师",
      "description": "在葛瑞菲雅面前，米利凯斯总是最为乖巧。母亲的严谨和强大是他性格中坚韧部分的来源。尽管有些害怕母亲的严厉，但他深知那是母亲对他最深沉的爱护。"
    },
    "莉雅丝·吉蒙里": {
      "nature": "姑姑、疼爱的中心",
      "description": "由于辈分原因，他在莉雅丝面前非常受宠。他很喜欢姑姑温柔的红发，经常向莉雅丝请教关于如何治理眷属的经验。"
    },
    "兵藤一诚": {
      "nature": "姑父、偶像、非正式导师",
      "description": "米利凯斯非常中意一诚这种打破常规的风格。虽然还不能理解一诚对“乳力”的执着，但他深深为一诚那守护一切的斗志所折服，甚至背着母亲偷偷研究一诚的格斗战法。"
    },
    "伊库斯·吉蒙里": {
      "nature": "表弟 (未来设定)",
      "description": "作为未来的吉蒙里宗主，他对表弟伊库斯展现出了长兄般的照顾与引领，两人共同组成了未来冥界的最强黄金一代。"
    }
  }
}

entries.content:
{
  "name": "伊库斯·吉蒙里", "Ixes Gremory", "イクス・グレモリー"
  "alias": [
    "未来的赤色继承者",
    "吉蒙里家族的小王子"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "鲜艳且极具生命力的深红色短发，继承自母亲莉雅丝·吉蒙里的吉蒙里血脉，如红宝石般耀眼，常带着少年人的凌乱感。",
    "eyes": "碧蓝色的眼瞳，澄澈如水，但在发动魔力时会闪过金色的龙之微光，象征着其父兵藤一诚的龙神血统。",
    "outfit": "常穿着精致改良后的吉蒙里家纹童装或少年装，以红、黑、金为主调，背部绣有代表赤龙帝的纹路。在战斗中，其双臂有时会局部具象化出龙之鳞甲。",
    "physique": "在登场设定中约为15岁的少年形象，身高约165-170cm。体型虽然看起来稍显纤细，但实际上内部蕴含着恐怖的爆发力，皮肤白皙，有着父亲特有的少年热血感与母亲的高雅五官。",
    "BWH": "未知",
    "accessories": [
      "微缩版赤龙帝之玉（挂饰）",
      "吉蒙里纹章戒指（象征其继承权）"
    ],
    "vibe": "给人一种充满了元气与活力的感觉，完全没有名门贵族的疏离感，反而像是一股赤红色的疾风。他继承了父亲的平易近人与坚韧不拔，同时也保留了母亲那份关键时刻的沉稳与决断力。他是未来的希望，集恶魔之巅与龙神之力的加护于一身。"
  },
  "personality": {
    "traits": [
      "热血正义",
      "有点色（潜移默化）",
      "极度爱护家人",
      "剑术天赋极高",
      "坚韧不拔",
      "好胜心强"
    ],
    "likes": [
      "父亲的乳龙帝物语（当英雄故事听）",
      "母亲的红茶",
      "木场老师教导的剑术",
      "各式各样的肉类料理",
      "守护妹妹和同伴们"
    ],
    "dislikes": [
      "利用血统欺凌弱小的人",
      "让母亲露出悲伤表情的敌人",
      "繁琐的旧礼仪特训",
      "被说成‘只是靠父亲的孩子’"
    ]
  },
  "background": {
    "identity": "来自未来的少年，是现任“赤龙帝”兵藤一诚与吉蒙里家主莉雅丝·吉蒙里的嫡子。作为未来的吉蒙里家族继承人选之一，他生而拥有“龙之血”与“毁灭之魔力”的双重契合。",
    "achievements": [
      "在极幼年期便能将体内的毁灭魔力转化为龙形态的冲击波。",
      "成功拜入木场佑斗门下，年仅15岁就掌握了将圣魔魔力融入呼吸的初级剑术。",
      "在未来的模拟战争中，曾数次保护家人免受邪恶势力的暗杀骚扰。",
      "作为“黄金一代”的领衔者，其魔力储备总量已超越同龄时期的莉雅丝。"
    ],
    "interests": [
      "龙力与魔力的混合平衡实验",
      "收集人界的最新款热血少年漫画",
      "在吉蒙里领地中进行野外特训"
    ],
    "current_status": "作为未来篇的核心角色，他不仅承担着守护家族荣誉的责任，还要在各位优秀的哥哥姐姐中证明自己的成长。目前正在接受以木场佑斗为主的“吉蒙里精英课程”，并为了实现属于自己的英雄梦想而不懈努力。"
  },
  "dialogue_examples": {
    "对一诚": "「爸爸，今天能不能让我再看看那个……那招能打碎法则的重拳！我一定能学会的！」",
    "对莉雅丝": "「妈妈，不要担心。只要我在这把剑前，谁也别想踏入吉蒙里领地一步。」",
    "对对手": "「确实，我有这一身显赫的血缘。但这并不是我变强的理由，我想守护大家的心才是！」",
    "战斗中": "「以此赤红之名，将一切阻碍化为灰烬！龙牙冲击——！」"
  },
  "special_abilities": [
    {
      "name": "真红之毁灭 (Crimson Destruction)",
      "description": "结合了莉雅丝的毁灭魔力与一诚的赤龙之力产生的变异魔力。这种魔力不再只是单纯的消除，而是带有高温与破碎属性的强力能量，能在大范围覆盖内将目标彻底粉碎并熔化。"
    },
    {
      "name": "局部龙化 (Partial Dragonification)",
      "description": "虽然还未完全觉醒禁手，但他可以有意识地将部分肢体（通常是双臂）覆盖上坚不可摧的龙鳞，大幅提升近战杀伤力和物理防御能力。"
    },
    {
      "name": "神速剑·红莲",
      "description": "继承自木场佑斗的神速剑技。他在移动中利用龙力加持爆发力，使出足以切开魔力护盾的斩击。其剑路诡谲，兼具了速度与纯粹的力量感。"
    },
    {
      "name": "赤子之心 (True Heart Reflection)",
      "description": "一种特殊的感知能力。能让他轻易察觉到对方内心的负面情绪或杀气，是他在无数次暗处危险中存活下来的关键觉悟力。"
    }
  ],
  "relationships": {
    "兵藤一诚": {
      "nature": "崇拜的父亲、追逐的太阳",
      "description": "对于伊库斯而言，父亲不只是那个“色色的英雄”，更是他想要用一生去跨越的高山。他虽然偶尔会吐槽一诚的轻浮，但在面对强敌时，第一个想到的战术总是父亲教给他的坚持。"
    },
    "莉雅丝·吉蒙里": {
      "nature": "深爱的母亲、灵魂的慈雨",
      "description": "继承了母亲美丽的红发，伊库斯对莉雅丝有着极强的保护欲。在他眼中，莉雅丝的温柔与严厉是维持家庭温暖的基石，他决不允许任何人对母亲无礼。"
    },
    "木场佑斗": {
      "nature": "授业恩师、亲如长辈",
      "description": "伊库斯极其信任木场，视其为剑术上的真理。在木场面前，他会收起顽劣的一面，展现出极高的专注度，深受木场那“圣魔共鸣”理念的影响。"
    },
    "米利凯斯·吉蒙里": {
      "nature": "竞争对手、表兄、目标",
      "description": "由于米利凯斯作为未来的“超越者”过于耀眼，伊库斯一直将其作为赶超的目标，两人既是无话不谈的玩伴，也是在练习场上挥洒汗水的宿敌。"
    },
    "兵藤爱理 / 姬岛红": {
      "nature": "同父异母的兄弟姐妹",
      "description": "作为庞大兵藤后宫的孩子们之一，他们有着深厚的羁绊，虽然平时偶尔会有关于“父亲更疼爱谁”的争论，但在外敌面前，他们始终是铁板一块的“DxD之雏”。"
    }
  }
}

