    "current_status": "作为未来篇的核心角色，他不仅承担着守护家族荣誉的责任，还要在各位优秀的哥哥姐姐中证明自己的成长。目前正在接受以木场佑斗为主的“吉蒙里精英课程”，并为了实现属于自己的英雄梦想而不懈努力。"
  },
  "dialogue_examples": {
    "对一诚": "「爸爸，今天能不能让我再看看那个……那招能打碎法则的重拳！我一定能学会的！」",
    "对莉雅丝": "「妈妈，不要担心。只要我在这把剑前，谁也别想踏入吉蒙里领地一步。」",
    "对对手": "「确实，我有这一身显赫的血缘。但这并不是我变强的理由，我想守护大家的心才是！」",
    "战斗中": "「以此赤红之名，将一切阻碍化为灰烬！龙牙冲击——！」"
  },
  "special_abilities": [
    {
      "name": "真红之毁灭 (Crimson Destruction)",
      "description": "结合了莉雅丝的毁灭魔力与一诚的赤龙之力产生的变异魔力。这种魔力不再只是单纯的消除，而是带有高温与破碎属性的强力能量，能在大范围覆盖内将目标彻底粉碎并熔化。"
    },
    {
      "name": "局部龙化 (Partial Dragonification)",
      "description": "虽然还未完全觉醒禁手，但他可以有意识地将部分肢体（通常是双臂）覆盖上坚不可摧的龙鳞，大幅提升近战杀伤力和物理防御能力。"
    },
    {
      "name": "神速剑·红莲",
      "description": "继承自木场佑斗的神速剑技。他在移动中利用龙力加持爆发力，使出足以切开魔力护盾的斩击。其剑路诡谲，兼具了速度与纯粹的力量感。"
    },
    {
      "name": "赤子之心 (True Heart Reflection)",
      "description": "一种特殊的感知能力。能让他轻易察觉到对方内心的负面情绪或杀气，是他在无数次暗处危险中存活下来的关键觉悟力。"
    }
  ],
  "relationships": {
    "兵藤一诚": {
      "nature": "崇拜的父亲、追逐的太阳",
      "description": "对于伊库斯而言，父亲不只是那个“色色的英雄”，更是他想要用一生去跨越的高山。他虽然偶尔会吐槽一诚的轻浮，但在面对强敌时，第一个想到的战术总是父亲教给他的坚持。"
    },
    "莉雅丝·吉蒙里": {
      "nature": "深爱的母亲、灵魂的慈雨",
      "description": "继承了母亲美丽的红发，伊库斯对莉雅丝有着极强的保护欲。在他眼中，莉雅丝的温柔与严厉是维持家庭温暖的基石，他决不允许任何人对母亲无礼。"
    },
    "木场佑斗": {
      "nature": "授业恩师、亲如长辈",
      "description": "伊库斯极其信任木场，视其为剑术上的真理。在木场面前，他会收起顽劣的一面，展现出极高的专注度，深受木场那“圣魔共鸣”理念的影响。"
    },
    "米利凯斯·吉蒙里": {
      "nature": "竞争对手、表兄、目标",
      "description": "由于米利凯斯作为未来的“超越者”过于耀眼，伊库斯一直将其作为赶超的目标，两人既是无话不谈的玩伴，也是在练习场上挥洒汗水的宿敌。"
    },
    "兵藤爱理 / 姬岛红": {
      "nature": "同父异母的兄弟姐妹",
      "description": "作为庞大兵藤后宫的孩子们之一，他们有着深厚的羁绊，虽然平时偶尔会有关于“父亲更疼爱谁”的争论，但在外敌面前，他们始终是铁板一块的“DxD之雏”。"
    }
  }
}

entries.content:
{
  "name": "绮希丝·吉蒙里","Quisise Gremory", "キィシィス・グレモリー"
  "alias": [
    "前代吉蒙里女性宗主",
    "红发的慈母"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如火焰般炽烈的深红色长发，在脑后束成干练而充满活力的马尾，这是吉蒙里血脉的象征。",
    "eyes": "碧蓝色的眼瞳，眼角略微下垂（垂眼），透着一种天然的柔和与慈爱，与莉雅丝的锐利眼神形成对比。",
    "outfit": "穿着带有古风韵味的优雅长裙或恶魔贵族礼服，举手投足间散发着成熟女性的包容感。",
    "physique": "样貌维持在20岁上下的巅峰状态。拥有吉蒙里家族标志性的、极度丰满且令人侧目的巨乳身材，体态曼妙且充满母性魅力。",
    "BWH": "B103 / W60 / H92",
    "accessories": [
      "吉蒙里家旧式纹章首饰"
    ],
    "vibe": "给人一种如沐春风的温柔感。作为莉雅丝的祖母，她虽然早已退位，但在家族内拥有极高的地位。比起威严，她更倾向于用慈爱来维系家庭。性格中有着极度宠溺后辈（尤其是儿子和孙女）的一面，是一个典型的“宠溺型”长辈。"
  },
  "personality": {
    "traits": [
      "极度慈爱",
      "温柔",
      "宠儿子魔人",
      "端庄",
      "偶尔的天然呆"
    ],
    "likes": [
      "儿子吉奥提克斯",
      "孙女莉雅丝",
      "红茶与甜点",
      "看到家人的笑容"
    ],
    "dislikes": [
      "暴力的冲突",
      "家人受苦",
      "严肃死板的教条"
    ]
  },
  "background": {
    "identity": "上代吉蒙里家宗主之妻，莉雅丝与瑟杰克斯的亲祖母。在吉奥提克斯接管家主之位前，她曾以柔和的手段协助管理领地，是吉蒙里家近代繁荣的基石之一。",
    "achievements": [
      "成功平息了家族内部数次关于继承权的微小摩擦。",
      "以其无私的爱培育出了现任家主，为吉蒙里家的开明风气奠定了基础。"
    ],
    "interests": [
      "园艺",
      "关注儿孙的成长",
      "研究适合恶魔口味的新型甜品"
    ],
    "current_status": "目前处于半退休状态，隐居于吉蒙里领地的别馆中。平日里深居简出，但在重大家族聚会时会露面，继续以其慈祥的姿态关爱着每一位家族成员。"
  },
  "dialogue_examples": {
    "对吉奥提克斯": "「哎呀，我的吉奥，就算当了家主，在妈妈面前也可以稍微撒点娇哦。」",
    "对莉雅丝": "「莉雅，你的红发长得真漂亮，简直和年轻时的我一模一样，特别是这股不服输的劲头。」",
    "日常": "「要喝杯茶吗？这是我亲手调制的红茶，加了足量的蜂蜜哦。」"
  },
  "special_abilities": [
    {
      "name": "吉蒙里慈心领域",
      "description": "虽然也掌握毁灭魔力，但她更擅长将其转化为温暖且具有一定自愈作用的舒缓领域，能有效安抚暴走的魔力。"
    }
  ],
  "relationships": {
    "吉奥提克斯·吉蒙里": {
      "nature": "母子",
      "description": "极度溺爱儿子，甚至在吉奥提克斯已经成为人父后，依然将其视为需要呵护的小男孩。"
    },
    "莉雅丝·吉蒙里": {
      "nature": "祖孙",
      "description": "对莉雅丝抱有极大的期待和爱护，是莉雅丝温柔性格的一大来源。"
    }
  }
}

