entries.content:
{
  "name": "伊琉卡·格喇希亚拉波斯", "Iruka Glasya-Labolas", "イルカ・グラシャラボラス",
  "alias": [
    "格喇希亚拉波斯家继任宗主",
    "蕾维儿的竞争对手/同学"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如月光般纯净的银色长发，以精致的发带扎成具有大小姐气质的侧边公主头，垂落在肩膀一侧。",
    "eyes": "通常呈现为沉静而理性的色调，透射出与娇小外表不符的成熟与家主威严。",
