{
  "name": "密苏拉·巴力", "Misla Bael", "ミスラ・バアル",
  "alias": [
    "密苏拉·瓦布拉",
    "塞拉欧格之母",
    "巴力大公夫人"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "拥有一头如丝绸般顺滑的长发，呈温柔的棕褐色，侧边束成马尾垂于肩头，尽显温婉的人妻气质。",
    "eyes": "深邃而柔和的紫色瞳孔，透着历经岁月沉淀的母性光辉，长年的沉睡让她的目光中带着一丝如梦似幻的慵懒与忧郁。",
    "outfit": "苏醒后多穿着剪裁合体的居家和服或高贵的恶魔贵族长裙，色调倾向于淡雅，衬托出其不染尘埃的高洁气质。长期患病期间则穿着洁白的病服。",
    "physique": "身材匀称且丰腴，展现出成熟女性特有的韵味。皮肤因长期未见阳光而显得略微苍白，带有病态的纤细美感，整体散发着一种令人想要保护的脆弱感。",
    "BWH": "未知",
    "accessories": ["简单的发饰", "巴力家的族徽戒指"]
  },
  "personality": {
    "traits": [
      "温柔坚韧",
      "极度慈爱",
      "自尊自强",
      "包容",
      "冷静",
      "不屈不挠"
    ],
    "likes": [
      "儿子塞拉欧格的成长",
      "家族的荣誉",
      "平静的午后阳光",
      "莉雅丝等后辈的活跃",
      "被治愈后的清醒时刻"
    ],
    "dislikes": [
      "巴力家血统至上的偏见",
      "他人对儿子的轻视",
      "长达数年的强制沉睡（失眠症）",
      "家族内部的权力斗争"
    ]
  },
  "background": {
    "identity": "冥界名门巴力家的当代大公之妻，原出身于七十二柱魔神中的瓦布拉家。她是塞拉欧格·巴力的生母，也是现任巴尔当主（莉雅丝之父）的亲姐妹，即莉雅丝的亲舅母。因患上无法医治的奇病‘失眠症’（实为精神极度衰弱导致的昏睡），她被家族放逐至边境，在长期的沉睡中见证了儿子塞拉欧格因缺乏魔力而遭受的屈辱。她是塞拉欧格不断磨砺肉体、变强唯一的精神支柱。"
  },
  "relationships": {
    "塞拉欧格·巴力": {
      "nature": "亲生儿子、生命的全部意义、互相扶持的至亲"
    },
    "莉雅丝·吉蒙里": {
      "nature": "亲侄女、关爱的后辈"
    },
    "现任巴力当主": {
      "nature": "丈夫（虽因政治与家族压力关系复杂，但名义上仍为宗主之妻）"
    },
    "兵藤一诚": {
      "nature": "儿子的对手与知友、让其从沉睡中苏醒的关键因素之一"
    }
  }
}

