  "name": "拉得拉·布涅", "Ladra Buné", "ラドラ・ブネ",
  "alias": [
    "拉得拉",
    "巨龙化之恶魔",
    "混血的雏龙"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "略显凌乱的深色短发，透着一股不羁的野性味道。",
    "eyes": "呈现出带有龙类特征的竖瞳，在激动或准备发动能力时会散发出淡淡的幽光。",
    "outfit": "穿着方便活动的紧身战斗服，外披带有龙鳞纹路装饰的轻甲，以此彰显其混血血统的骄傲。",
    "physique": "常态下保持着强健的人类青年体型，但由于拥有「巨龙变化」的能力，在战斗中能够瞬间化身为覆盖着厚重鳞片、体型巨大的西洋巨龙。",
    "BWH": "未知",
    "accessories": ["布涅家族印记", "恶魔棋子-城堡"]
  },
  "personality": {
    "traits": [
      "自尊心强",
      "冷静敏锐",
      "拥有龙之孤傲",
      "对家族观念淡薄",
      "极度敬仰强者"
    ],
    "likes": [
      "在高空翱翔的感觉",
      "磨砺自身的龙之力量",
      "塞拉欧格那种打破常理的纯粹力量",
      "证明混血者的价值"
    ],
    "dislikes": [
      "血统歧视",
      "被家族陈腐的规则束缚",
      "过于吵闹的环境"
    ]
  },
  "background": {
    "identity": "恶魔名门布涅家与人类的混血儿，虽然身为上级恶魔，但其出身让他更倾向于用实力证明自己。作为塞拉欧格·巴力的「城堡（Rook）」，他拥有变身成巨龙的恐怖天赋，在第一届排名游戏国际大会中扮演着空战与强袭的核心角色。他将塞拉欧格视为真正能看清其内在价值的主君，为此甘愿收起龙的傲慢，在紫金之狮子王旗下驰骋战场。"
  },
  "relationships": {
    "塞拉欧格·巴力": {
      "nature": "领袖、指引者、不仅看重血统而看重实力的人",
    },
    "刚多玛·巴拉姆": {
      "nature": "前卫拍档、共同构建防线的战友",
    },
    "布涅家高层": {
      "nature": "冷淡、仅仅只有血缘关系的束缚",
    }
  }
}

entries.content:
"name": "可利安娜·安德雷斐斯","Coriana Andrealphus", "コリアナ・アンドレアルフス"
  "alias": [
    "薹挺",
    "塞拉欧格的主教",
    "安德雷斐斯家成员"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "拥有一头波浪状的长卷发，颜色为明亮的金黄色，如同正午的阳光般耀眼，流露出上级恶魔特有的高贵气质。",
    "eyes": "双眸呈现出晶莹的粉红色（或浅红色），眼神中透着自信与从容，仿佛一切战场局势都在其掌握之中。",
    "outfit": "常穿着深蓝色的修身西装制服，内搭粉色衬衫，下身是齐膝的西装裙，展现出干练的职场知性美。在排名游戏正式场合则会换上更具防御性或礼仪性的魔导礼服。",
    "physique": "身材丰满而匀称，拥有极其出众的曲线，不仅有着傲人的上围，长腿也显得优雅有力，举手投足间散发出一种成熟女性恶魔的魅力。",
    "BWH": "未知",
    "accessories": ["魔导增幅戒指"],
  },
  "personality": {
    "traits": [
      "冷静睿智",
      "忠诚不渝",
      "优雅从容",
      "极具团队精神",
      "魔法造诣深厚",
      "外柔内刚"
    ],
    "likes": [
      "辅助塞拉欧格达成目标",
      "研究高阶支援魔法",
      "观察战场动态",
      "巴力家的崛起",
      "团队协作的胜利"
    ],
    "dislikes": [
      "弱者的胆怯",
      "无法控制的变数",
      "对塞拉欧格的诋毁",
      "无效的魔法消耗"
    ]
  },
  "background": {
    "identity": "冥界上级恶魔家族安德雷斐斯家的直系成员。她在塞拉欧格·巴力还在因不具备毁灭魔力而受尽嘲讽时就选择了跟随他，成为其排名游戏团队中的“主教（Bishop）”。她不仅是团队中的智囊之一，更是精通各类复杂魔法支援的专家。在第一届排名游戏国际大会中，作为“紫金之狮子王”队的成员，她以精密的魔法支援确保了团队的稳健进攻。",
  },
  "relationships": {
    "塞拉欧格·巴力": {
      "nature": "效忠的主公、深层信任的战友、仰慕的对象",
    },
    "列格瓦尔·泽尼温": {
      "nature": "同队骑士、相互配合的攻守伙伴",

    },
    "莉雅丝·吉蒙里": {
      "nature": "竞争对手、对等地位的恶魔名门后裔",

    },
    "嘉比德": {
      "nature": "同队士兵、并肩作战的伙伴",

    }
  }
}

