entries.content:
{
  "name": "米斯蒂塔·撒伯纳克", "Misteta Sabnock", "ミスティータ・サブナック",
  "alias": [
    "米斯蒂塔",
    "异能之棺持有者",
    "塞拉欧格的主教"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "留着一头清爽的浅绿色（青色）短发，发型整齐，给人一种知性而文静的印象。",
    "eyes": "深邃的淡紫色瞳孔，透着沉稳与内敛，同时也带着一丝作为混血恶魔的忧郁感。",
    "outfit": "通常穿着带有宗教神职人员风格的长袍，外披一件以白色为主、带有金色滚边和兜帽的连帽披风。长袍内部为深蓝色的神职服饰，腰间束有华丽的皮带，整体装束尽显其作为“主教”的角色身份。",
    "physique": "身材娇小纤细，给人一种柔弱且需要保护的错觉。虽体格不强健，但体内潜藏着惊人的精神意志力。身高约155cm左右。",
    "BWH": "未知",
    "accessories": ["巨大的暗紫色十字形法杖（疑似神器异能之棺的载体）", "额头前的兜帽饰品"]
  },
  "personality": {
    "traits": [
      "文静内向",
      "自我牺牲精神",
      "意志坚定",
      "忠诚",
      "冷静",
      "包容"
    ],
    "likes": [
      "塞拉欧格的霸气",
      "同伴间的牵绊",
      "安静的祈祷环境",
      "超越血统的努力"
    ],
    "dislikes": [
      "歧视混血的恶魔贵族",
      "无谓的争斗",
      "自身的无力感",
      "对自己耐力极限的恐惧"
    ]
  },
  "background": {
    "identity": "冥界纯血恶魔名门“撒伯纳克”家与人类的混血后代。虽然拥有上级恶魔的血脉，但因混血身份曾遭遇冷落。现担任塞拉欧格·巴力的“主教（Bishop）”，是其眷属中的核心辅助与控制力量。在第一届排名游戏国际大会（Azazel Cup）中，作为“紫金之狮子王”队的成员出战，凭借牺牲性的封印能力为队伍提供战略支撑。"
  },
  "abilities": {
    "sacred_gear": "异能之棺（Dimple Helm / Forbidden Invade）",
    "ability_desc": "一种强力且具有禁忌性质的神器。米斯蒂塔通过将自身的体力与精神力压榨至极限，甚至透支生命力为代价，在一定时间内能完全封印特定对手的能力或神器，是跨等级作战的杀手锏。"
  },
  "relationships": {
    "塞拉欧格·巴力": {
      "nature": "主公、崇拜对象、精神支柱"
    },
    "孔帕罗·罗利希特": {
      "nature": "战友、同为塞拉欧格眷属的同僚"
    },
    "紫金之狮子王队成员": {
      "nature": "生死与共的伙伴"
    }
  }
}

