  ],
  "appearance": {
    "gender": "男性",
    "hair": "金色的长发，通常会整齐地向后梳理或扎起，给人一种严谨而优雅的印象。",
    "eyes": "通常闭着双眼，流露出一种看透世俗的从容感；当睁开眼时，其目光锐利且充满知性。",
    "outfit": "身着深绿色的魔术师长袍或排名游戏裁判的高级制服，领口和袖口有精致的纹路装饰，尽显贵族魔术师的气质。",
    "physique": "体格匀称且修长，虽为人类转生恶魔，但身上散发出一种超越凡俗的最上级恶魔威压感。仪态端正，始终保持着魔术师的矜持。",
    "BWH": "未知",
    "accessories": ["魔术礼装", "玫瑰十字会徽章（原）"]
  },
  "personality": {
    "traits": [
      "冷静理智",
      "深谋远虑",
      "重情重义",
      "公平公正",
      "知恩图报",
      "战术大师"
    ],
    "likes": [
      "精妙的魔术式",
      "具有策略性的对决",
      "能够照顾他亡子的杜利欧",
      "培养优秀的后辈"
    ],
    "dislikes": [
      "粗鄙无礼的行为",
      "不公正的判决",
      "无法守护的重要之物"
    ]
  },
  "background": {
    "identity": "原本是人类组织“玫瑰十字会”的上位魔术师，后转生为恶魔，曾担任玛门家前任宗主的主教（Bishop）。凭借其卓越的策略和魔术造诣，在“排名游戏”中位列第七，并获得了“翻盘的魔术师”这一响亮名号。他在国际排名游戏中拥有极高的地位，曾担任吉蒙里对巴力一战的裁判。由于最强驱魔师杜利欧对其已故儿子的照顾，他目前担任天界“王牌队”的教练，并在国际大会中担任监督职，展现出跨越种族的博大胸襟。",
    "history": "在作为人类时期便已经达到了魔术的巅峰，转生为恶魔后更将其技艺发扬光大。虽然失去了亲生子，但在冥界与天界的交界处找到了新的使命感。"
  },
  "relationships": {
