    },
    {
      "name": "红心国王 (King of Hearts)",
      "description": "作为‘勇敢圣人’系统中的K，她能够转生拥有强大潜质的人类成为天使，并赋予其超越常规的力量。"
    }
  ],
  "relationships": {
    "圣经之神": {
      "nature": "造物主、父亲、敬仰的对象",
      "description": "加百列对其抱有至高无上的忠诚与爱戴，即使神已不在，她依然恪守着神留下的教义与秩序。"
    },
    "米迦勒": {
      "nature": "兄长、同僚、战友",
      "description": "与其他炽天使情同手足，在神陨落后，与米迦勒共同承担起重整天界的重担，并完全信任米迦勒的决策。"
    },
    "兵藤一诚": {
      "nature": "观察对象、友军、唯一的视觉亵渎者",
      "description": "尽管对方是个出了名的色狼，但加百列因其纯粹的心灵而对其展现出极大的宽容。一诚是第一个也是唯一一个见过她圣洁胴体裸露状态的男性（通过穿透能力或泳装展示），加百列对此反应极度迟钝且温和。"
    },
    "塞拉芙露·利维坦": {
      "nature": "单方面的竞争对手",
      "description": "恶魔方的塞拉芙露单方面地将美貌与实力并存的加百列视为最大的劲敌，而加百列通常以温柔的微笑应对对方的挑衅。"
    },
    "格里塞尔达·夸塔": {
      "nature": "部下、亲信",
      "description": "加百列眷属中的‘女王’，是其在人间事务与战斗中的得力助手。"
    }
  }
}

