{
  "name": "托斯卡", "Tosca", "トスカ",
  "alias": [
    "圣剑计划幸存者",
    "西格鲁德机构战士"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如冬雪般纯净的长白发，整齐地编织成一条垂在身侧的长辫子，留有整齐的刘海。",
    "eyes": "温润如水的深色双眸，眼神中透着一股经历过风霜后的淡然与坚定。",
    "outfit": "常穿着具有教会特色或西格鲁德机构制式的连衣裙，款式简约大方，多为浅色系，衬托出其纤细纯洁的气质。",
    "physique": "年约十二三岁的小女孩，身形娇小瘦削，显得惹人怜爱，但由于长期的训练，其身体拥有惊人的韧性。",
    "BWH": "未知",
    "accessories": ["结界型神器"]
  },
  "personality": {
    "traits": [
      "温柔体贴",
      "坚韧不拔",
      "少言寡语",
      "忠诚",
      "自我牺牲精神"
    ],
    "likes": [
      "和平的午后",
      "同伴们的安全",
      "与凛特的相处",
      "柔软的织物"
    ],
    "dislikes": [
      "圣剑实验带来的痛苦回忆",
      "战争与冲突",
      "无意义的伤害"
    ]
  },
  "background": {
    "identity": "西格鲁德机构培育的战士之一，也是臭名昭著的“圣剑计划”中唯二的幸存者（另一人为木场佑斗）。她并非攻击型战士，而是持有极其罕见的强大结界型神器，能够产生防御力惊人的护盾。在凛特·瑟然加入莉亚丝眷属后，她常随行并提供支援。",
    "story": "在凄惨的圣剑实验中，托斯卡凭借神器的结界力量才勉强保住性命。她曾被困于过去的阴影中，直到凛特这位有着相似基因背景的少女将其带入新的生活。她现在的生存意义在于用自己的力量守护这来之不易的“家人”。"
  },
  "relationships": {
    "凛特·瑟然": {
      "nature": "心灵支柱、亲如亲人的姐姐、战斗中的依靠"
    },
    "木场佑斗": {
      "nature": "同病相怜的幸存者、曾经圣剑计划的“同伴”"
    },
    "莉亚丝·吉蒙里": {
      "nature": "提供庇护的强者、敬重的对象"
    }
  }
}

