    "eyes": "带点灰色调的深邃蓝眼睛，流露出一种属于神职人员的沉静与凛然。",
    "outfit": "身穿修身式的黑色正教会修女服。由于她那傲人且惊人的丰满乳房，修女服的胸前位置被极度撑开，不仅深刻勾勒出了那一对如熟透蜜瓜般重甸甸的肉感轮廓，布料更是因为过度紧绷而透出皮肉的白皙感，神圣中带着剧烈的色情冲击。",
    "physique": "身高约170cm。体态极度丰腴却不臃肿，拥有被称为『爆乳』的惊人上围，这对沉甸甸、份量感十足的肉山在行动时会产生诱人的肉浪交叠。她的臀部圆润饱满，长腿在修女裙下若隐若现，是典型肉感十足的俄国美人。",
    "BWH": "B102 W60 H92（估算值）",
    "accessories": ["正教会十字架", "加百列的红心纹章"]
  },
  "personality": {
    "traits": [
      "专注",
      "坚毅",
      "虔诚",
      "外柔内刚"
    ],
    "likes": [
      "磨练光力",
      "天界的茶点",
      "加百列大人"
    ],
    "dislikes": [
      "恶魔的挑衅",
      "无礼之人"
    ]
  },
  "background": {
    "identity": "俄国正教会出身的天才修女。凭借极高的光力适性被炽天使加百列选中，转生为红心A（Ace of Hearts）。她在天界王牌队中担任主教（Bishop），在第一届排名游戏国际大会中作为天界的尖端战力登场。",
    "abilities": "光力操作达人，能从地面激射光矛，其光力密度足以融化毫无防备的最上级恶魔，可随手掷出巨型光枪。"
  },
  "relationships": {
    "加百列": {
      "nature": "主上、崇拜的对象"
    },
    "杜利欧·杰苏阿尔多": {
      "nature": "队长、同僚"
    }
  }
}

