{
  "name": "萨麦尔", "Samael", "サマエル",
  "alias": [
    "食龙者",
    "神的怨毒",
    "原初之罪",
    "终极屠龙者",
    "伊甸园之蛇"
  ],
  "appearance": {
    "gender": "未知（诅咒的聚合体）",
    "hair": "无",
    "eyes": "被沉重的拘束具密封，缝隙中不断渗出令人心碎的血泪，蕴含着无尽的痛苦与嫉妒。",
    "outfit": "全身上下覆盖着极度紧绷的束缚具，上面刻满了诅咒的经文与令人不适的文字。其身体被无数粗大的钉子贯穿并固定在无形的十字架上。",
    "physique": "畸形而恐怖的姿态。上半身维持着堕天使的形态，下半身则是蜿蜒如东方龙般的细长蛇躯。双臂被束缚，尾部呈现蛇状，周身笼罩着不断扩张的黑色雾气与充满杀意的气焰。",
    "BWH": "未知",
    "accessories": ["神之拘束具", "穿身十字架"],
  },
  "personality": {
    "traits": [
      "极度痛苦",
      "充满嫉妒",
      "纯粹的恶意",
      "怨恨一切龙族",
      "静谧的疯狂"
    ],
    "likes": [
      "吞噬龙族",
      "诅咒的扩散",
      "鲜血与哀嚎"
    ],
    "dislikes": [
      "所有的龙类",
      "神圣的光芒",
      "智慧果实的记忆"
    ]
  },
  "background": {
    "identity": "传说中引诱人类始祖触犯原初之罪的邪恶化身。因承受了神对蛇类及龙类的所有极端恶意的结晶，他成为了凌驾于所有屠龙武器之上的禁忌存在。萨麦尔并非因实力强大而令人恐惧，而是因为他本身就是专门为灭绝龙族而存在的剧毒。由于力量过于凶恶，他被永久封印在冥府最下层的寒冰地狱科基托斯之中，只有极少数极高位的存在能通过复杂的仪式进行短时间的召唤。",
  },
  "relationships": {
    "圣经之神": {
      "nature": "诅咒的来源、施加封印者、曾经的主宰",
    },
    "奥菲斯/天龙": {
      "nature": "天敌、诅咒捕杀的对象、深深怨恨的目标",
    },
    "格奥尔克": {
      "nature": "召唤者（短期契约）",
    }
  }
}

