    "outfit": "身披奢华而庄严的深黑色祭司长袍，边缘绣有暗金色的复杂咒纹。头戴象征冥王权力的尖顶白金皇冠，周身萦绕着令人窒息的死亡气息。",
    "physique": "外表是一具散发着古老韵味的洁白骸骨，骨架高大且坚固。虽然没有血肉，但其存在本身便散发着作为希腊神话主神的顶级威压感。",
    "BWH": "未知",
    "accessories": ["冥王权杖", "灵魂王冠"]
  },
  "personality": {
    "traits": [
      "冷静残酷",
      "极度厌恶他系神话",
      "保守主义",
      "实干家",
      "幕后黑手",
      "极度理智",
      "神祇的傲慢"
    ],
    "likes": [
      "冥府的秩序",
      "纯粹的死亡规律",
      "人类（以正常的视角看待）",
      "达成目的的效率"
    ],
    "dislikes": [
      "希腊以外的其他神话体系",
      "扰乱死亡秩序的存在",
      "无限龙神奥菲斯",
      "天界与现世的平衡"
    ]
  },
  "background": {
    "identity": "希腊神话体系中的主神之一，统领死亡国度冥府的最高主宰。他拥有神灵中顶尖的战斗力，是冥府运行不可或缺的核心。他极度排斥其他神话体系对死亡领域的干涉。为了捕获无限龙神奥菲斯以扩充自身实力并终结混沌，他不惜与祸之团合作，违规允许曹操召唤食龙者萨麦尔，并协助李泽维姆潜入天界。他利用莉莉丝进行人工恶魔实验，策划了企图颠覆现有超自然秩序的‘地狱事变’。",
    "history": [
      "远古时代起便坐镇冥府，维持生死轮回。",
      "对奥菲斯的力量产生觊觎，将其视为威胁与目标。",
      "与李泽维姆、洛基等反叛者结成‘地狱盟主联盟’。",
      "策划地狱事变，试图确立冥府在所有神话体系中的绝对主导地位。"
    ]
  },
  "relationships": {
    "曹操": {
      "nature": "利用工具、暂时的盟友，为其提供萨麦尔的召唤许可",
    },
    "李泽维姆·李维安·路西法": {
      "nature": "合伙人、共犯，协助其实现混乱目的以达成自己的利益",
    },
    "奥菲斯": {
      "nature": "妄图捕获的目标、被视为需要排除或掌控的力量根源",
    },
    "莉莉丝": {
      "nature": "实验对象、用于制造人工恶魔的‘母体’工具",
    },
    "兵藤一诚/瓦利": {
      "nature": "需要铲除的阻碍、卑微的棋子（在其早期视角中）"
    }
  }
}

